    "nil": "NIL",
    "true": "TRUE",
    "false": "FALSE",
    "or": "OR",
    "and": "AND",
    "not": "NOT",
}

class Lexer:
    def __init__(self, src, filename):
        self.src=src
        self.filename=filename
        self.pos=0
        self.line=1
        self.col=0
        self.n=len(src)
        self.tokens=[]
        self.errors=[]  # list of (line,col,msg)
        self.inline=[]  # inline errors for lex output (line,col,msg)
        self.cmd_depth=0
    def peek(self, off=0):
        i=self.pos+off
        if i>=self.n:
            return '\0'
        return self.src[i]
    def advance(self):
        ch=self.src[self.pos]
        self.pos+=1
        if ch=='\n':
            self.line+=1
            self.col=0
        else:
            self.col+=1
        return ch
    def add(self, typ, val, line, col, raw):
        self.tokens.append(Token(typ,val,line,col,raw))
    def err(self, line, col, msg, inline=False):
        self.errors.append((line,col,msg))
        if inline:
            self.inline.append((line,col,msg))
    def lex(self):
        if self.src.startswith("#!"):
            while self.pos<self.n and self.peek()!='\n':
                self.advance()
            if self.pos<self.n:
                self.advance()
        while self.pos<self.n:
            sl=self.line
            sc=self.col
            ch=self.peek()
            if ch in ' \t\r':
                self.advance(); continue
            if ch=='\n':
                self.advance(); continue
            if ch=='#':
                while self.pos<self.n and self.peek()!='\n':
                    self.advance()
                continue
            if ch=='$' and self.peek(1)=='{':
                self.advance(); self.advance()
                self.add('DOLLAR_LBRACE','${',sl,sc,'${')
                self.cmd_depth+=1
                continue
            if ch=='&' and self.peek(1)=='{':
                self.advance(); self.advance()
                self.add('AMP_LBRACE','&{',sl,sc,'&{')
                self.cmd_depth+=1
                continue
            if ch=='{':
                self.advance()
                self.add('LBRACE','{',sl,sc,'{')
                self.cmd_depth+=1
                continue
            if ch=='}':
                self.advance()
                self.add('RBRACE','}',sl,sc,'}')
                if self.cmd_depth>0:
                    self.cmd_depth-=1
                continue
            if self.cmd_depth>0:
                if ch=='|':
                    self.advance(); self.add('PIPE','|',sl,sc,'|'); continue
                if ch==';':
                    self.advance(); self.add('SEMI',';',sl,sc,';'); continue
                if ch=='?':
                    self.advance(); self.add('QUESTION','?',sl,sc,'?'); continue
                if ch=='<' and self.peek(1)=='<':
                    self.advance(); self.advance(); self.add('LTLT','<<',sl,sc,'<<'); continue
                if ch=='>' and self.peek(1)=='>':
                    self.advance(); self.advance(); self.add('GTGT','>>',sl,sc,'>>'); continue
                if ch in ('>','<'):
                    self.advance(); self.add(ch,ch,sl,sc,ch); continue
                if ch=='"':
                    self.lex_string(sl,sc,inside=True); continue
                if ch=="'":
                    self.lex_char(sl,sc); continue
                if ch=='$':
                    nxt=self.peek(1)
                    if nxt=='{':
                        self.advance(); self.advance()
                        ident=''
                        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                            ident+=self.peek(); self.advance()
                        if self.pos<self.n and self.peek()=='}':
                            self.advance()
                            raw='${{'+ident+'}}'
                            self.add('CMD_VAR',ident,sl,sc,raw)
                        else:
                            self.err(sl,sc,"unterminated variable",inline=True)
                            raw='${{'+ident+'}}'
                            self.add('CMD_VAR',ident,sl,sc,raw)
                        continue
                    elif nxt.isalpha() or nxt=='_':
                        self.advance()
                        ident=''
                        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                            ident+=self.peek(); self.advance()
                        raw='${{'+ident+'}}'
                        self.add('CMD_VAR',ident,sl,sc,raw)
                        continue
                    else:
                        self.advance()
                        self.err(sl,sc,"unexpected '$'.",inline=False)
                        continue
