                word=''
                wline=sl; wcol=sc
                while self.pos<self.n:
                    c=self.peek()
                    if c in ' \t\r\n#|;><&}':
                        break
                    if c in ('"',"'"):
                        break
                    if c=='$':
                        break
                    if c=='{' or c=='}':
                        break
                    if c=='?':
                        break
                    word+=c
                    self.advance()
                if word!='':
                    self.add('WORD',word,wline,wcol,word)
                    continue
                self.advance()
                self.err(sl,sc,f"unexpected '{ch}'.",inline=False)
                continue
            else:
                if ch=='"':
                    self.lex_string(sl,sc,inside=False); continue
                if ch=="'":
                    self.lex_char(sl,sc); continue
                if ch.isdigit():
                    self.lex_number(sl,sc); continue
                if ch.isalpha() or ch=='_':
                    self.lex_ident(sl,sc); continue
                if ch=='+' and self.peek(1)=='+':
                    self.advance(); self.advance(); self.add('PLUSPLUS','++',sl,sc,'++'); continue
                if ch=='=' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add('EQEQ','==',sl,sc,'=='); continue
                if ch=='!' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add('NEQ','!=',sl,sc,'!='); continue
                if ch=='<' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add('LTE','<=',sl,sc,'<='); continue
                if ch=='>' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add('GTE','>=',sl,sc,'>='); continue
                if ch=='<' and self.peek(1)=='<':
                    self.advance(); self.advance(); self.add('LTLT','<<',sl,sc,'<<'); continue
                if ch=='>' and self.peek(1)=='>':
                    self.advance(); self.advance(); self.add('GTGT','>>',sl,sc,'>>'); continue
                if ch=='@' and self.peek(1)=='[':
                    self.advance(); self.advance(); self.add('AT_LBRACK','@[',sl,sc,'@['); continue
                single_map={
                    '=':'EQ',
                    '+':'PLUS',
                    '-':'MINUS',
                    '*':'STAR',
                    '/':'SLASH',
                    '%':'PERCENT',
                    ':':'COLON',
                    ',':'COMMA',
                    ';':'SEMI',
                    '.':'DOT',
                    '(':'LPAREN',
                    ')':'RPAREN',
                    '[':'LBRACK',
                    ']':'RBRACK',
                    '{':'LBRACE',
                    '}':'RBRACE',
                    '|':'PIPE',
                    '>':'GT',
                    '<':'LT',
                    '?':'QUESTION',
                    '&':'AMP',
                    '!':'BANG',
                    '$':'DOLLAR',
                }
