                    self.add(single_map[ch],ch,sl,sc,ch)
                    continue
                self.advance()
                self.err(sl,sc,f"unexpected '{ch}'.",inline=False)
        return self.tokens

    def lex_string(self, line, col, inside=False):
        self.advance()
        buf=[]
        raw=['"']
        closed=False
        while self.pos<self.n:
            ch=self.peek()
            if ch=='"':
                self.advance()
                raw.append('"')
                closed=True
                break
            if ch=='\\':
                esc_col=self.col
                self.advance()
                if self.pos>=self.n:
                    self.err(line, esc_col, "invalid escape sequence '\\'.", inline=True)
                    buf.append('\\')
                    raw.append('\\')
                    break
                esc=self.peek()
                self.advance()
                raw.append('\\'+esc)
                if esc=='n':
                    buf.append('\n')
                elif esc=='t':
                    buf.append('\t')
                elif esc=='"':
                    buf.append('"')
                elif esc=="'":
                    buf.append("'")
                elif esc=='\\':
                    buf.append('\\')
                elif esc=='0':
                    buf.append('\0')
                else:
                    self.err(line, esc_col, f"invalid escape sequence '\\{esc}'.", inline=True)
                    buf.append('\0')
                continue
            if ch=='\n':
                self.err(line, col, "unterminated string", inline=False)
                break
            if inside and ch=='$':
                nxt=self.peek(1)
                if nxt=='{':
                    self.advance(); self.advance()
                    ident=''
                    while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                        ident+=self.peek(); self.advance()
                    if self.pos<self.n and self.peek()=='}':
                        self.advance()
                        placeholder='${{'+ident+'}}'
                        buf.append(placeholder)
                        raw.append(placeholder)
                    else:
                        self.err(line,col,"unterminated variable",inline=True)
                    continue
                elif nxt.isalpha() or nxt=='_':
                    self.advance()
                    ident=''
                    while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                        ident+=self.peek(); self.advance()
                    placeholder='${{'+ident+'}}'
                    buf.append(placeholder)
                    raw.append(placeholder)
                    continue
                else:
                    buf.append('$')
                    raw.append('$')
                    self.advance()
                    continue
            else:
                buf.append(ch)
                raw.append(ch)
                self.advance()
        s=''.join(buf)
        raw_str=''.join(raw)
        self.add('STRING', s, line, col, raw_str)

    def lex_char(self, line, col):
        self.advance()
        if self.pos>=self.n:
            self.err(line,col,"unterminated char",inline=False)
            return
        ch=self.peek()
        if ch=='\\':
            esc_col=self.col
            self.advance()
            if self.pos>=self.n:
                self.err(line,col,"invalid escape",inline=True)
                return
            esc=self.peek()
            self.advance()
            if esc not in ('n','t','"',"'" ,'\\','0'):
                self.err(line, esc_col, f"invalid escape sequence '\\{esc}'.", inline=True)
                val='\0'
                raw="'\\0'"
            else:
                if esc=='n':
                    val='\n'
                elif esc=='t':
                    val='\t'
                elif esc=='"':
                    val='"'
                elif esc=="'":
                    val="'"
                elif esc=='\\':
                    val='\\'
                elif esc=='0':
                    val='\0'
                else:
                    val=esc
                raw=f"'\\{esc}'"
        else:
            val=ch
            raw=f"'{ch}'"
            self.advance()
        if self.pos<self.n and self.peek()=="'":
            self.advance()
            self.add('CHAR', val, line, col, raw)
            return
        else:
            # handle extra chars before closing
            closing=self.src.find("'", self.pos)
            if closing!=-1:
                for i in range(self.pos, closing):
                    ce=self.src[i]
                    ecol=self.col + (i - self.pos)
                    self.err(self.line, ecol, f"unexpected '{ce}'.", inline=False)
                cnt= closing - self.pos + 1
                for _ in range(cnt):
                    self.advance()
                self.add('CHAR', val, line, col, raw)
                return
            else:
                self.err(line,col,"unterminated char",inline=False)
                self.add('CHAR', val, line, col, raw)
                return

    def lex_ident(self, line, col):
        s=''
        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
            s+=self.peek()
            self.advance()
        typ=KEYWORDS.get(s, 'IDENT')
        self.add(typ, s, line, col, s)

    def lex_number(self, line, col):
        num_str=''
        while self.pos<self.n and self.peek().isdigit():
            num_str+=self.peek()
            self.advance()
        has_dot=False
        if self.pos<self.n and self.peek()=='.':
            if self.pos+1<self.n and self.peek(1).isdigit():
                has_dot=True
                num_str+='.'
                self.advance()
                while self.pos<self.n and self.peek().isdigit():
                    num_str+=self.peek()
                    self.advance()
        has_exp=False
        if self.pos<self.n and self.peek() in ('e','E'):
            if self.pos+1<self.n and self.peek(1).isdigit():
                has_exp=True
                expc=self.peek()
                self.advance()
                num_str+=expc
                while self.pos<self.n and self.peek().isdigit():
                    num_str+=self.peek()
                    self.advance()
        raw=num_str
        norm=raw
        try:
            if 'e' in raw.lower():
                mant, exp = raw.lower().split('e')
                mant_val=float(mant)
                exp_val=int(exp)
                val=mant_val*(10**exp_val)
                if float(val).is_integer():
                    norm=str(int(val))
                else:
                    norm=str(val)
                    if norm.endswith('.0'):
                        norm=norm[:-2]
            else:
                if not has_dot and not has_exp:
                    norm=str(int(raw)) if raw!='' else '0'
                else:
                    norm=raw
        except:
            norm=raw
        if has_dot or has_exp:
            try:
                v=float(raw)
            except:
                v=0.0
            self.add('FLOAT', v, line, col, norm)
        else:
            try:
                v=int(norm)
            except:
                v=0
            self.add('INT', v, line, col, norm)

PYEOF

