        if not t:
            return None
        if t.typ=='LET':
            return self.parse_let()
        if t.typ=='IF':
            return self.parse_if_stmt()
        if t.typ=='FOR':
            return self.parse_for()
        if t.typ=='WHILE':
            return self.parse_while()
        if t.typ=='RETURN':
            return self.parse_return()
        if t.typ=='BREAK':
            self.consume('BREAK')
            return ('break',)
        if t.typ=='LBRACE' or t.typ=='DOLLAR_LBRACE' or t.typ=='AMP_LBRACE':
            return self.parse_command_block()
        if t.typ=='IDENT' and self.pos+1<len(self.tokens) and self.tokens[self.pos+1].typ=='EQ':
            # assign
            name=self.consume('IDENT')
            self.consume('EQ')
            expr=self.parse_expr()
            return ('assign', name.val, expr, name.line, name.col)
        # expression statement
        expr=self.parse_expr()
        # consume optional semicolon? The semicolon token is SE MI? For statement termination, but we treat as separate? For expression statements, semicolon not required.
        # If next is SEMI, consume
        if not self.at_end() and self.peek().typ=='SEMI':
            self.consume('SEMI')
        return ('expr', expr)
    def parse_let(self):
        self.consume('LET')
        if self.at_end():
            self.error(None, "unexpected end of file")
            return None
        ident=self.peek()
        if ident and ident.typ=='IDENT':
            self.consume('IDENT')
            var=ident.val
            line=ident.line
            col=ident.col
            if not self.at_end() and self.peek().typ=='EQ':
                self.consume('EQ')
                expr=self.parse_expr()
                return ('let', var, expr, line, col)
            else:
                return ('let', var, None, line, col)
        else:
            self.error(self.peek(), "expected identifier")
            return None
    def parse_if_stmt(self):
        self.consume('IF')
        cond=self.parse_expr()
        self.consume('THEN')
        then_branch=[]
        while not self.at_end() and self.peek().typ not in ('ELSE','END'):
            s=self.parse_stmt()
            if s: then_branch.append(s)
        else_branch=None
        if not self.at_end() and self.peek().typ=='ELSE':
            self.consume('ELSE')
            else_branch=[]
            while not self.at_end() and self.peek().typ!='END':
                s=self.parse_stmt()
                if s: else_branch.append(s)
        self.consume('END')
        return ('if', cond, then_branch, else_branch)
    def parse_for(self):
        self.consume('FOR')
        var_tok=self.consume('IDENT')
        var=var_tok.val if var_tok else 'i'
        self.consume('IN')
        iterable=self.parse_expr()
        self.consume('DO')
        body=[]
        while not self.at_end() and self.peek().typ!='END':
            s=self.parse_stmt()
            if s: body.append(s)
        self.consume('END')
        return ('for', var, iterable, body)
    def parse_while(self):
        self.consume('WHILE')
        cond=self.parse_expr()
        self.consume('DO')
        body=[]
        while not self.at_end() and self.peek().typ!='END':
            s=self.parse_stmt()
            if s: body.append(s)
        self.consume('END')
        return ('while', cond, body)
    def parse_return(self):
        self.consume('RETURN')
        if not self.at_end() and self.peek().typ not in ('END','ELSE','SEMI','RBRACE'):
            expr=self.parse_expr()
            return ('return', expr)
        else:
            return ('return', None)
    def parse_command_block(self):
        # Handles { ... }, ${ ... }, &{ ... }
        start=self.consume()
        typ=start.typ
        # Gather command nodes
        # For simplicity, parse commands as list of pipelines
        cmds=[]
        current_pipeline=[]
        current_cmd_parts=[]
        # Helper to flush current command
        def flush_cmd():
            nonlocal current_cmd_parts, current_pipeline
            if current_cmd_parts:
                current_pipeline.append(current_cmd_parts)
                current_cmd_parts=[]
        def flush_pipeline():
            nonlocal current_pipeline, cmds
            flush_cmd()
            if current_pipeline:
                cmds.append(current_pipeline)
                current_pipeline=[]
        while not self.at_end() and self.peek().typ!='RBRACE':
            tok=self.peek()
            if tok.typ=='SEMI':
                flush_pipeline()
                self.consume('SEMI')
                continue
            if tok.typ=='PIPE':
                flush_cmd()
                self.consume('PIPE')
                continue
            if tok.typ in ('WORD','STRING','CHAR','CMD_VAR','IDENT','AT_LBRACK','LBRACK','LPAREN','INT','FLOAT'):
                # For command words, treat WORD etc as word
                # For redirections: > < >> << etc are handled separately
                # Check if next is redirection?
                self.consume()
                current_cmd_parts.append(tok)
                continue
            if tok.typ in ('GT','LT','LTLT','GTGT'):
                # redirection operator
                op=self.consume()
                # Next token may be WORD or STRING or CMD_VAR or number?
                # For 2> etc, the previous token was '2' as INT? But we handled '2' as INT token? In command mode, '2' is WORD? Actually for "2>&1", lex gave tokens "2", ">", "&1"
                # So for redirection with fd, the fd is separate token before operator
                # Our parsing currently lumps fd as previous word? The current_cmd_parts may have last part as fd.
                # We'll treat redirection as part of current command: include operator and target
                # Consume target
                if not self.at_end():
                    tgt=self.peek()
                    # Target could be WORD or STRING or CMD_VAR or digits
                    if tgt.typ in ('WORD','STRING','CHAR','CMD_VAR','IDENT','INT'):
                        self.consume()
                        current_cmd_parts.append(op)
                        current_cmd_parts.append(tgt)
                    else:
                        current_cmd_parts.append(op)
                else:
                    current_cmd_parts.append(op)
                continue
            if tok.typ in ('GT','LT'):
                # already handled?
                self.consume()
                continue
            if tok.typ=='WORD' or tok.typ=='STRING':
                self.consume()
                current_cmd_parts.append(tok)
                continue
            # For digit redirection like "2" then ">" then "&1": the "2" would have been consumed as WORD/INT before, then ">" handles
            # So we need to handle standalone '>' etc
            # For simplicity, just consume unknown
            self.consume()
            current_cmd_parts.append(tok)
        # Expect closing }
        if not self.at_end() and self.peek().typ=='RBRACE':
            self.consume('RBRACE')
        flush_pipeline()
        if typ=='LBRACE':
            return ('cmd', cmds)
        elif typ=='DOLLAR_LBRACE':
            return ('capture', cmds)
        elif typ=='AMP_LBRACE':
            return ('async', cmds)
        else:
            return ('cmd', cmds)

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left=self.parse_and()
        while not self.at_end() and self.peek().typ=='OR':
            self.consume('OR')
            right=self.parse_and()
            left=('binop','or',left,right)
        return left
    def parse_and(self):
        left=self.parse_comparison()
        while not self.at_end() and self.peek().typ=='AND':
            self.consume('AND')
            right=self.parse_comparison()
            left=('binop','and',left,right)
        return left
    def parse_comparison(self):
        left=self.parse_concat()
        while not self.at_end() and self.peek().typ in ('EQEQ','NEQ','LTE','GTE','LT','GT'):
            op=self.consume()
            mapping={'EQEQ':'==','NEQ':'!=','LTE':'<=','GTE':'>=','LT':'<','GT':'>'}
            right=self.parse_concat()
            left=('binop',mapping[op.typ],left,right)
        return left
    def parse_concat(self):
        left=self.parse_add()
        while not self.at_end() and self.peek().typ=='PLUSPLUS':
            self.consume('PLUSPLUS')
            right=self.parse_add()
            left=('binop','++',left,right)
        return left
    def parse_add(self):
        left=self.parse_mul()
        while not self.at_end() and self.peek().typ in ('PLUS','MINUS'):
            op=self.consume()
            right=self.parse_mul()
            left=('binop',op.val,left,right)
        return left
    def parse_mul(self):
        left=self.parse_unary()
        while not self.at_end() and self.peek().typ in ('STAR','SLASH','PERCENT'):
            op=self.consume()
            right=self.parse_unary()
            left=('binop',op.val,left,right)
        return left
    def parse_unary(self):
        if not self.at_end() and self.peek().typ=='NOT':
            self.consume('NOT')
            expr=self.parse_unary()
            return ('unop','not',expr)
        if not self.at_end() and self.peek().typ=='MINUS':
            # check if it's unary minus
            self.consume('MINUS')
            expr=self.parse_unary()
            return ('unop','-',expr)
        return self.parse_postfix()
    def parse_postfix(self):
        left=self.parse_primary()
        while True:
            if self.at_end():
                break
            tok=self.peek()
            if tok.typ=='DOT' and self.pos+1<len(self.tokens) and self.tokens[self.pos+1].typ=='IDENT':
                self.consume('DOT')
                field=self.consume('IDENT')
                left=('dot',left,field.val,field.line,field.col)
                continue
            if tok.typ=='LBRACK':
                self.consume('LBRACK')
                idx=self.parse_expr()
                self.consume('RBRACK')
                left=('index',left,idx)
                continue
            if tok.typ=='LPAREN':
                self.consume('LPAREN')
                args=[]
                while not self.at_end() and self.peek().typ!='RPAREN':
                    args.append(self.parse_expr())
                    if not self.at_end() and self.peek().typ=='COMMA':
                        self.consume('COMMA')
                    else:
                        break
                self.consume('RPAREN')
                left=('call',left,args)
                continue
            break
        return left
    def parse_primary(self):
        if self.at_end():
            self.error(None, "unexpected end of file")
            return ('nil',)
        tok=self.peek()
        if tok.typ=='INT':
            self.consume('INT')
            return ('int',tok.val)
        if tok.typ=='FLOAT':
            self.consume('FLOAT')
            return ('float',tok.val)
        if tok.typ=='STRING':
            self.consume('STRING')
            return ('string',tok.val)
        if tok.typ=='CHAR':
            self.consume('CHAR')
            return ('char',tok.val)
        if tok.typ=='NIL':
            self.consume('NIL')
            return ('nil',)
        if tok.typ=='TRUE':
            self.consume('TRUE')
            return ('bool',True)
        if tok.typ=='FALSE':
            self.consume('FALSE')
            return ('bool',False)
        if tok.typ=='IDENT':
            self.consume('IDENT')
            return ('var',tok.val, tok.line, tok.col)
        if tok.typ=='SELF':
            self.consume('SELF')
            return ('self',)
        if tok.typ=='LPAREN':
            self.consume('LPAREN')
            expr=self.parse_expr()
            self.consume('RPAREN')
            return expr
        if tok.typ=='LBRACK':
            self.consume('LBRACK')
            elems=[]
            while not self.at_end() and self.peek().typ!='RBRACK':
                elems.append(self.parse_expr())
                if not self.at_end() and self.peek().typ=='COMMA':
                    self.consume('COMMA')
                else:
                    break
            self.consume('RBRACK')
            return ('array', elems)
        if tok.typ=='AT_LBRACK':
            self.consume('AT_LBRACK')
            pairs=[]
            while not self.at_end() and self.peek().typ!='RBRACK':
                # key: IDENT ':' expr or '[' expr ']' ':' expr ?
                key=None
                if self.peek().typ=='IDENT' and self.pos+1<len(self.tokens) and self.tokens[self.pos+1].typ=='COLON':
                    k=self.consume('IDENT')
                    self.consume('COLON')
                    key=k.val
                else:
                    # maybe string key? but hush dict keys are ident only
                    k=self.parse_expr()
                    self.consume('COLON')
                    # if k is string? treat as string key
                    if k[0]=='string':
                        key=k[1]
                    else:
                        key=str(k)
                val=self.parse_expr()
                pairs.append((key,val))
                if not self.at_end() and self.peek().typ=='COMMA':
                    self.consume('COMMA')
                else:
                    break
            self.consume('RBRACK')
            return ('dict', pairs)
        if tok.typ=='FUNCTION':
            self.consume('FUNCTION')
            self.consume('LPAREN')
            params=[]
            while not self.at_end() and self.peek().typ!='RPAREN':
                if self.peek().typ=='IDENT':
                    p=self.consume('IDENT')
                    params.append(p.val)
                # skip comma
                if not self.at_end() and self.peek().typ=='COMMA':
                    self.consume('COMMA')
                else:
                    break
            self.consume('RPAREN')
            body=[]
            while not self.at_end() and self.peek().typ!='END':
                s=self.parse_stmt()
                if s:
                    body.append(s)
            self.consume('END')
            return ('function', params, body)
        if tok.typ=='IF':
            self.consume('IF')
            cond=self.parse_expr()
            self.consume('THEN')
            then_branch=[]
            while not self.at_end() and self.peek().typ not in ('ELSE','END'):
                s=self.parse_stmt()
                if s: then_branch.append(s)
            else_branch=None
            if not self.at_end() and self.peek().typ=='ELSE':
                self.consume('ELSE')
                else_branch=[]
                while not self.at_end() and self.peek().typ!='END':
                    s=self.parse_stmt()
                    if s: else_branch.append(s)
            self.consume('END')
            return ('if_expr', cond, then_branch, else_branch)
        if tok.typ in ('LBRACE','DOLLAR_LBRACE','AMP_LBRACE'):
            # command block as expression?
            # For expression context, ${ ... } can be value, &{ ... } can be value
            # LBRACE as expression? Not typical, but handle
            return self.parse_command_block()
        # unknown
        self.error(tok, f"unexpected '{tok.raw}'")
        self.consume()
        return ('nil',)

def ast_to_string(node):
    # Convert AST node to string as per original --ast output
    if node is None:
        return ""
    typ=node[0]
    if typ=='let':
        _, var, expr, line, col = node
        if expr is None:
            return f"let {var} = nil"
        else:
            return f"let {var} = {expr_to_string(expr)}"
    if typ=='assign':
        _, var, expr, line, col = node
        return f"{var} = {expr_to_string(expr)}"
    if typ=='expr':
        return expr_to_string(node[1])
    if typ=='if':
        _, cond, then_branch, else_branch = node
        s=f"if {expr_to_string(cond)} then\n"
        for stmt in then_branch:
            s+= f"\t{ast_to_string(stmt)}\n"
        if else_branch is not None:
            s+= "else\n"
            for stmt in else_branch:
                s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ=='for':
        _, var, iterable, body = node
        s=f"for {var} in {expr_to_string(iterable)} do\n"
        for stmt in body:
            s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ=='while':
        _, cond, body = node
        s=f"while {expr_to_string(cond)} do\n"
        for stmt in body:
            s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ=='break':
        return "break"
    if typ=='return':
        _, expr = node
        if expr is None:
            return "return"
        else:
            return f"return {expr_to_string(expr)}"
    if typ in ('cmd','capture','async'):
        return cmd_to_string(node)
    return str(node)

def expr_to_string(node):
    if node is None:
        return "nil"
    typ=node[0]
    if typ=='int':
        return str(node[1])
    if typ=='float':
        v=node[1]
        # format to preserve? For 1.5 etc
        if isinstance(v,float):
            # remove trailing zeros? Original prints "1.5" etc, "890000000000" for 89e10?
            # For float, they printed as integer without .0 if it came from exponent? In AST, float from 89e10 was expanded to 890000000000 (no decimal). Our expr value is original float expanded? We'll use string of int if integer valued?
            if v.is_integer():
                # Check if original was exponent case: we lost info, but okay to print without decimal for integer-valued floats? In prior test, 1.2e3 gave 1200 not 1200.0 in lex, but in AST/ program, 1.2e3 was 1200 (int) as well. So we can print as int string.
                return str(int(v))
            else:
                # Need to preserve .5 etc
                # Use repr removing trailing?
                s=str(v)
                return s
        else:
            return str(v)
    if typ=='string':
        # Escape string for display: wrap in double quotes, escape \n etc?
        # Original string display escapes \n as \n? In lex we saw "hello \n world" displayed with \n.
        # In AST, string "hello" shows as "\"hello\""
        # For string value containing \n, original AST for "escape \n sequences" showed "\"escape \\n sequences \\\" are ...\""
        # So need to escape: \n -> \\n, \t -> \\t, \" -> \\\", \\ -> \\\\, \0 -> \\0
        s=node[1]
        esc=s.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\t','\\t').replace('\0','\\0')
        return f'"{esc}"'
    if typ=='char':
        v=node[1]
        # char display as '\'a\'' ?
        if v=='\n':
            esc='\\n'
        elif v=='\t':
            esc='\\t'
        elif v=="'":
            esc="\\'"
        elif v=='"':
            esc='\\"'
        elif v=='\\':
            esc='\\\\'
        elif v=='\0':
            esc='\\0'
        else:
            esc=v
        return f"'{esc}'"
    if typ=='nil':
        return "nil"
    if typ=='bool':
        return "true" if node[1] else "false"
    if typ=='var':
        return node[1]
    if typ=='self':
        return "self"
    if typ=='array':
        elems=node[1]
        if not elems:
            return "[ ]"
        inner=", ".join(expr_to_string(e) for e in elems)
        # Original prints [
        #   1,
        #   2
        # ]
        # For single line, they collapse? In AST sample, [1,2,3] prints as "[\n\t1,\n\t2,\n\t3\n]"
        # We'll just print as "[ 1, 2, 3 ]" for simplicity but need to match exactly.
        # For now, try to match original multiline for arrays with multiple elements?
        # We'll produce multiline if len>1?
        if len(elems)>1:
            parts=",\n\t".join(expr_to_string(e) for e in elems)
            return f"[\n\t{parts}\n]"
        else:
            return f"[ {inner} ]"
    if typ=='dict':
        pairs=node[1]
        if not pairs:
            return "@[ ]"
        lines=[]
        for k,v in pairs:
            lines.append(f"\t{k}: {expr_to_string(v)}")
        return "@[\n"+",\n".join(lines)+"\n]"
    if typ=='binop':
        _, op, left, right = node
        return f"({expr_to_string(left)} {op} {expr_to_string(right)})"
    if typ=='unop':
        _, op, expr = node
        if op=='not':
            return f"(not {expr_to_string(expr)})"
        else:
            return f"(- {expr_to_string(expr)})"
    if typ=='dot':
        _, obj, field, line, col = node
        return f"{expr_to_string(obj)}.{field}"
    if typ=='index':
        _, obj, idx = node
        return f"{expr_to_string(obj)}[{expr_to_string(idx)}]"
    if typ=='call':
        _, func, args = node
        args_str=", ".join(expr_to_string(a) for a in args)
        return f"{expr_to_string(func)}({args_str})"
    if typ=='function':
        _, params, body = node
        s=f"function({', '.join(params)})\n"
        for stmt in body:
            s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ=='if_expr':
        _, cond, then_branch, else_branch = node
        s=f"if {expr_to_string(cond)} then\n"
        for stmt in then_branch:
            s+= f"\t{ast_to_string(stmt)}\n"
        if else_branch is not None:
            s+= "else\n"
            for stmt in else_branch:
                s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ in ('cmd','capture','async'):
        return cmd_to_string(node)
    return str(node)

def cmd_to_string(node):
    typ=node[0]
    cmds=node[1]
    # cmds is list of pipelines, each pipeline is list of commands, each command is list of tokens
    # For AST, they print as:
    # {
    #     "echo" "hi"
    # }
    # For pipelines: "echo" "hi" | "cat"
    # For with redirections: "echo" "hi" 1>"file"
    # We'll reconstruct
    if not cmds:
        return "{ ***ill-formed*** ? }"
    lines=[]
    for pipeline in cmds:
        # pipeline is list of commands (each command is list of tokens)
        # For simplicity, we have cmds as list of pipelines where each pipeline is list of command parts? In parser, we built cmds as list of pipelines, but current structure is: cmds = list of pipelines, each pipeline is list of command token lists.
        # However our parser built cmds as list of pipelines where each pipeline appended current_pipeline which is list of command token lists.
        # Example: "echo hi | cat" => cmds = [[ [WORD echo, WORD hi], [WORD cat] ]]
        # For "{ echo hi }", cmds = [ [ [echo, hi] ] ] -> one pipeline with one command
        # We'll handle both cases where pipeline may be flat
        if not pipeline:
            continue
        # If pipeline is list of command token lists, join with " | "
        cmd_strs=[]
        for cmd_tokens in pipeline:
            # cmd_tokens is list of Token
            parts=[]
            for tok in cmd_tokens:
                if tok.typ=='WORD':
                    # quote word as "word"
                    parts.append(f'"{tok.val}"')
                elif tok.typ=='STRING':
                    # STRING token's val already decoded, need to re-escape for display as "string"
                    s=tok.val
                    # s may contain placeholder ${{...}}; for display, we need to quote placeholder as "${{...}}" ?
                    # For command string "\"hello ${{x}}\"", we want "\"hello ${{x}}\""
                    # Our STRING val contains placeholder, we can display as original raw? Use raw
                    # Use token.raw for display
                    parts.append(f'"{tok.raw[1:-1]}"' if tok.raw.startswith('"') else f'"{tok.val}"')
                    # Simplify: use raw
                    parts[-1]=f'"{tok.raw[1:-1]}"' if len(tok.raw)>=2 else '""'
                elif tok.typ=='CHAR':
                    # CHAR raw is like "'a'"
                    parts.append(tok.raw)
                elif tok.typ=='CMD_VAR':
                    # display as "${{var}}"
                    parts.append(f'"${{{tok.val}}}"')  # Actually displayed as "${{x}}" without quotes? In lex, CMD_VAR inside command is "${{x}}" (without quotes)
                    # For AST, they display as "\"${{x}}\""? Let's check: earlier AST for { echo $x } was not tested. For ${ echo $x }, AST showed "echo" "${args}" ?
                    # In AST for `let error = ${ echo $args }`, AST was "echo" "${args}" (quoted)
                    parts[-1]=f'"${{{tok.val}}}"' if tok.typ=='CMD_VAR' else parts[-1]
                    # Actually better to keep as quoted string for AST
                elif tok.typ in ('GT','LT','LTLT','GTGT','PIPE','SEMI'):
                    parts.append(tok.raw)
                else:
                    parts.append(tok.raw)
            cmd_strs.append(" ".join(parts))
        lines.append(" | ".join(cmd_strs))
    # Now produce final block
    if typ=='LBRACE' or typ=='cmd':
        # original prints {
        # \t"echo" "hi"
        # }
        inner="\n".join(f"\t{line}" for line in lines)
        return "{\n" + inner + "\n}"
    elif typ=='capture': # ${ ... }
        inner="\n".join(f"\t{line}" for line in lines)
        return "${\n" + inner + "\n}"
    elif typ=='async': # &{ ... }
        inner="\n".join(f"\t{line}" for line in lines)
        return "&{\n" + inner + "\n}"
    else:
        inner="\n".join(lines)
        return inner

