DASH="--------------------------------------------------"

class Token:
    __slots__=('typ','val','line','col','raw')
    def __init__(self,typ,val,line,col,raw):
        self.typ=typ
        self.val=val
        self.line=line
        self.col=col
        self.raw=raw

KEYWORDS={"let":"LET","if":"IF","then":"THEN","else":"ELSE","end":"END","for":"FOR","in":"IN","do":"DO","while":"WHILE","function":"FUNCTION","return":"RETURN","break":"BREAK","self":"SELF","nil":"NIL","true":"TRUE","false":"FALSE","or":"OR","and":"AND","not":"NOT"}

class Lexer:
    def __init__(self,src,filename):
        self.src=src
        self.filename=filename
        self.pos=0
        self.line=1
        self.col=0
        self.n=len(src)
        self.tokens=[]
        self.errors=[]
        self.lex_items=[]
        self.cmd_depth=0
    def peek(self,off=0):
        i=self.pos+off
        return self.src[i] if i<self.n else '\0'
    def advance(self):
        ch=self.src[self.pos]
        self.pos+=1
        if ch=='\n':
            self.line+=1
            self.col=0
        else:
            self.col+=1
        return ch
    def add_token(self,typ,val,line,col,raw):
        t=Token(typ,val,line,col,raw)
        self.tokens.append(t)
        self.lex_items.append(('token',t))
    def err_inline(self,line,col,msg):
        self.errors.append((line,col,msg))
        self.lex_items.append(('error',line,col,msg))
    def err(self,line,col,msg):
        self.errors.append((line,col,msg))
    def lex(self):
        if self.src.startswith("#!"):
            while self.pos<self.n and self.peek()!='\n':
                self.advance()
            if self.pos<self.n:
                self.advance()
        while self.pos<self.n:
            sl=self.line
            sc=self.col
            ch=self.peek()
            if ch in ' \t\r':
                self.advance(); continue
            if ch=='\n':
                self.advance(); continue
            if ch=='#':
                while self.pos<self.n and self.peek()!='\n':
                    self.advance()
                continue
            if ch=='$' and self.peek(1)=='{':
                self.advance(); self.advance()
                self.add_token('DOLLAR_LBRACE','${',sl,sc,'${')
                self.cmd_depth+=1
                continue
            if ch=='&' and self.peek(1)=='{':
                self.advance(); self.advance()
                self.add_token('AMP_LBRACE','&{',sl,sc,'&{')
                self.cmd_depth+=1
                continue
            if ch=='{':
                self.advance()
                self.add_token('LBRACE','{',sl,sc,'{')
                self.cmd_depth+=1
                continue
            if ch=='}':
                self.advance()
                self.add_token('RBRACE','}',sl,sc,'}')
                if self.cmd_depth>0:
                    self.cmd_depth-=1
                continue
            if self.cmd_depth>0:
                if ch=='|':
                    self.advance(); self.add_token('PIPE','|',sl,sc,'|'); continue
                if ch==';':
                    self.advance(); self.add_token('SEMI',';',sl,sc,';'); continue
                if ch=='?':
                    self.advance(); self.add_token('QUESTION','?',sl,sc,'?'); continue
                if ch=='<' and self.peek(1)=='<':
                    self.advance(); self.advance(); self.add_token('LTLT','<<',sl,sc,'<<'); continue
                if ch=='>' and self.peek(1)=='>':
                    self.advance(); self.advance(); self.add_token('GTGT','>>',sl,sc,'>>'); continue
                if ch in ('>','<'):
                    self.advance(); self.add_token(ch,ch,sl,sc,ch); continue
                if ch=='"':
                    self.lex_string(sl,sc,inside=True); continue
                if ch=="'":
                    self.lex_char(sl,sc); continue
                if ch=='$':
                    nxt=self.peek(1)
                    if nxt=='{':
                        self.advance(); self.advance()
                        ident=''
                        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                            ident+=self.peek(); self.advance()
                        if self.pos<self.n and self.peek()=='}':
                            self.advance()
                            raw='${{'+ident+'}}'
                            self.add_token('CMD_VAR',ident,sl,sc,raw)
                        else:
                            self.err_inline(sl,sc,"unterminated variable")
                            raw='${{'+ident+'}}'
                            self.add_token('CMD_VAR',ident,sl,sc,raw)
                        continue
                    elif nxt.isalpha() or nxt=='_':
                        self.advance()
                        ident=''
                        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                            ident+=self.peek(); self.advance()
                        raw='${{'+ident+'}}'
                        self.add_token('CMD_VAR',ident,sl,sc,raw)
                        continue
                    else:
                        self.advance()
                        self.err_inline(sl,sc,"unexpected '$'.")
                        continue
                word=''
                wline=sl; wcol=sc
                while self.pos<self.n:
                    c=self.peek()
                    if c in ' \t\r\n#|;><&}':
                        break
                    if c in ('"',"'"):
                        break
                    if c=='$':
                        break
                    if c=='{' or c=='}':
                        break
                    if c=='?':
                        break
                    word+=c
                    self.advance()
                if word!='':
                    self.add_token('WORD',word,wline,wcol,word)
                    continue
                self.advance()
                self.err_inline(sl,sc,f"unexpected '{ch}'.")
                continue
            else:
                if ch=='"':
                    self.lex_string(sl,sc,inside=False); continue
                if ch=="'":
                    self.lex_char(sl,sc); continue
                if ch.isdigit():
                    self.lex_number(sl,sc); continue
                if ch.isalpha() or ch=='_':
                    self.lex_ident(sl,sc); continue
                if ch=='+' and self.peek(1)=='+':
                    self.advance(); self.advance(); self.add_token('PLUSPLUS','++',sl,sc,'++'); continue
                if ch=='=' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add_token('EQEQ','==',sl,sc,'=='); continue
                if ch=='!' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add_token('NEQ','!=',sl,sc,'!='); continue
                if ch=='<' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add_token('LTE','<=',sl,sc,'<='); continue
                if ch=='>' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add_token('GTE','>=',sl,sc,'>='); continue
                if ch=='<' and self.peek(1)=='<':
                    self.advance(); self.advance(); self.add_token('LTLT','<<',sl,sc,'<<'); continue
                if ch=='>' and self.peek(1)=='>':
                    self.advance(); self.advance(); self.add_token('GTGT','>>',sl,sc,'>>'); continue
                if ch=='@' and self.peek(1)=='[':
                    self.advance(); self.advance(); self.add_token('AT_LBRACK','@[',sl,sc,'@['); continue
                single_map={'=':'EQ','+':'PLUS','-':'MINUS','*':'STAR','/':'SLASH','%':'PERCENT',':':'COLON',',':'COMMA',';':'SEMI','.':'DOT','(':'LPAREN',')':'RPAREN','[':'LBRACK',']':'RBRACK','{':'LBRACE','}':'RBRACE','|':'PIPE','>':'GT','<':'LT','?':'QUESTION','&':'AMP','!':'BANG','$':'DOLLAR'}
                if ch in single_map:
                    if ch=='$':
                        self.advance()
                        self.err_inline(sl,sc,"unexpected '$'.")
                        continue
                    self.advance()
                    self.add_token(single_map[ch],ch,sl,sc,ch)
                    continue
                self.advance()
                self.err_inline(sl,sc,f"unexpected '{ch}'.")
        return self.tokens
    def lex_string(self,line,col,inside=False):
        self.advance()
        buf=[]
        raw=['"']
        while self.pos<self.n:
            ch=self.peek()
            if ch=='"':
                self.advance()
                raw.append('"')
                break
            if ch=='\\':
                esc_col=self.col
                self.advance()
                if self.pos>=self.n:
                    self.err_inline(line,esc_col,"invalid escape sequence '\\'.")
                    buf.append('\\')
                    raw.append('\\')
                    break
                esc=self.peek()
                self.advance()
                raw.append('\\'+esc)
                if esc=='n':
                    buf.append('\n')
                elif esc=='t':
                    buf.append('\t')
                elif esc=='"':
                    buf.append('"')
                elif esc=="'":
                    buf.append("'")
                elif esc=='\\':
                    buf.append('\\')
                elif esc=='0':
                    buf.append('\0')
                else:
                    self.err_inline(line,esc_col,f"invalid escape sequence '\\{esc}'.")
                    buf.append('\0')
                continue
            if ch=='\n':
                self.err(line,col,"unterminated string")
                break
            if inside and ch=='$':
                nxt=self.peek(1)
                if nxt=='{':
                    self.advance(); self.advance()
                    ident=''
                    while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                        ident+=self.peek(); self.advance()
                    if self.pos<self.n and self.peek()=='}':
                        self.advance()
                        placeholder='${{'+ident+'}}'
                        buf.append(placeholder)
                        raw.append(placeholder)
                    else:
                        self.err_inline(line,col,"unterminated variable")
                    continue
                elif nxt.isalpha() or nxt=='_':
                    self.advance()
                    ident=''
                    while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                        ident+=self.peek(); self.advance()
                    placeholder='${{'+ident+'}}'
                    buf.append(placeholder)
                    raw.append(placeholder)
                    continue
                else:
                    buf.append('$')
                    raw.append('$')
                    self.advance()
                    continue
            else:
                buf.append(ch)
                raw.append(ch)
                self.advance()
        s=''.join(buf)
        raw_str=''.join(raw)
        self.add_token('STRING',s,line,col,raw_str)
    def lex_char(self,line,col):
        self.advance()
        if self.pos>=self.n:
            self.err(line,col,"unterminated char")
            return
        ch=self.peek()
        if ch=='\\':
            esc_col=self.col
            self.advance()
            if self.pos>=self.n:
                self.err(line,col,"invalid escape")
                return
            esc=self.peek()
            self.advance()
            if esc not in ('n','t','"',"'" ,'\\','0'):
                self.err_inline(line,esc_col,f"invalid escape sequence '\\{esc}'.")
                val='\0'
                raw="'\\0'"
            else:
                if esc=='n':
                    val='\n'
                elif esc=='t':
                    val='\t'
                elif esc=='"':
                    val='"'
                elif esc=="'":
                    val="'"
                elif esc=='\\':
                    val='\\'
                elif esc=='0':
                    val='\0'
                else:
                    val=esc
                raw=f"'\\{esc}'"
        else:
            val=ch
            raw=f"'{ch}'"
            self.advance()
        if self.pos<self.n and self.peek()=="'":
            self.advance()
            self.add_token('CHAR',val,line,col,raw)
            return
        else:
            closing=self.src.find("'",self.pos)
            if closing!=-1:
                for i in range(self.pos,closing):
                    ce=self.src[i]
                    ecol=self.col + (i - self.pos)
                    self.err_inline(self.line,ecol,f"unexpected '{ce}'.")
                cnt= closing - self.pos + 1
                for _ in range(cnt):
                    self.advance()
                self.add_token('CHAR',val,line,col,raw)
                return
            else:
                self.err(line,col,"unterminated char")
                self.add_token('CHAR',val,line,col,raw)
                return
    def lex_ident(self,line,col):
        s=''
        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
            s+=self.peek()
            self.advance()
        typ=KEYWORDS.get(s,'IDENT')
        self.add_token(typ,s,line,col,s)
    def lex_number(self,line,col):
        num_str=''
        while self.pos<self.n and self.peek().isdigit():
            num_str+=self.peek()
            self.advance()
        has_dot=False
        if self.pos<self.n and self.peek()=='.':
            if self.pos+1<self.n and self.peek(1).isdigit():
                has_dot=True
                num_str+='.'
                self.advance()
                while self.pos<self.n and self.peek().isdigit():
                    num_str+=self.peek()
                    self.advance()
        has_exp=False
        if self.pos<self.n and self.peek() in ('e','E'):
            if self.pos+1<self.n and self.peek(1).isdigit():
                has_exp=True
                expc=self.peek()
                self.advance()
                num_str+=expc
                while self.pos<self.n and self.peek().isdigit():
                    num_str+=self.peek()
                    self.advance()
        raw=num_str
        norm=raw
        try:
            if 'e' in raw.lower():
                mant,exp = raw.lower().split('e')
                mant_val=float(mant)
                exp_val=int(exp)
                val=mant_val*(10**exp_val)
                if float(val).is_integer():
                    norm=str(int(val))
                else:
                    norm=str(val)
                    if norm.endswith('.0'):
                        norm=norm[:-2]
            else:
                if not has_dot and not has_exp:
                    norm=str(int(raw)) if raw!='' else '0'
                else:
                    norm=raw
        except:
            norm=raw
        if has_dot or has_exp:
            try:
                v=float(raw)
            except:
                v=0.0
            self.add_token('FLOAT',v,line,col,norm)
        else:
            try:
                v=int(norm)
            except:
                v=0
            self.add_token('INT',v,line,col,norm)

# Parser for AST
class Parser:
    def __init__(self, tokens, filename, source):
        self.tokens=tokens
        self.filename=filename
        self.source=source
        self.pos=0
        self.errors=[]
        self.n=len(tokens)
    def peek(self,off=0):
        if self.pos+off < self.n:
            return self.tokens[self.pos+off]
        return None
    def at_end(self):
        return self.pos>=self.n
    def consume(self, typ=None):
        if self.at_end():
            return None
        t=self.tokens[self.pos]
        if typ and t.typ!=typ:
            self.error(t,f"unexpected '{t.raw}', expected '{typ}'")
            return None
        self.pos+=1
        return t
    def error(self, token, msg):
        # token may be None -> use last
        if token:
            line=token.line
            col=token.col
        else:
            line=1
            col=0
        self.errors.append((line,col,msg))
    def match(self, *typs):
        if not self.at_end() and self.peek().typ in typs:
            self.pos+=1
            return True
        return False
    def parse(self):
        stmts=[]
        while not self.at_end():
            s=self.parse_stmt()
            if s is not None:
                stmts.append(s)
            else:
                # advance to avoid infinite loop
                if not self.at_end():
                    self.pos+=1
        return stmts
    def parse_stmt(self):
        t=self.peek()
        if not t:
            return None
        if t.typ=='LET':
            return self.parse_let()
        if t.typ=='IF':
            return self.parse_if_stmt()
        if t.typ=='FOR':
            return self.parse_for()
        if t.typ=='WHILE':
            return self.parse_while()
        if t.typ=='RETURN':
            return self.parse_return()
        if t.typ=='BREAK':
            self.consume('BREAK')
            return ('break',)
        if t.typ=='LBRACE' or t.typ=='DOLLAR_LBRACE' or t.typ=='AMP_LBRACE':
            return self.parse_command_block()
        if t.typ=='IDENT' and self.pos+1<len(self.tokens) and self.tokens[self.pos+1].typ=='EQ':
            # assign
            name=self.consume('IDENT')
            self.consume('EQ')
            expr=self.parse_expr()
            return ('assign', name.val, expr, name.line, name.col)
        # expression statement
        expr=self.parse_expr()
        # consume optional semicolon? The semicolon token is SE MI? For statement termination, but we treat as separate? For expression statements, semicolon not required.
        # If next is SEMI, consume
        if not self.at_end() and self.peek().typ=='SEMI':
            self.consume('SEMI')
        return ('expr', expr)
    def parse_let(self):
        self.consume('LET')
        if self.at_end():
            self.error(None, "unexpected end of file")
            return None
        ident=self.peek()
        if ident and ident.typ=='IDENT':
            self.consume('IDENT')
            var=ident.val
            line=ident.line
            col=ident.col
            if not self.at_end() and self.peek().typ=='EQ':
                self.consume('EQ')
                expr=self.parse_expr()
                return ('let', var, expr, line, col)
            else:
                return ('let', var, None, line, col)
        else:
            self.error(self.peek(), "expected identifier")
            return None
    def parse_if_stmt(self):
        self.consume('IF')
        cond=self.parse_expr()
        self.consume('THEN')
        then_branch=[]
        while not self.at_end() and self.peek().typ not in ('ELSE','END'):
            s=self.parse_stmt()
            if s: then_branch.append(s)
        else_branch=None
        if not self.at_end() and self.peek().typ=='ELSE':
            self.consume('ELSE')
            else_branch=[]
            while not self.at_end() and self.peek().typ!='END':
                s=self.parse_stmt()
                if s: else_branch.append(s)
        self.consume('END')
        return ('if', cond, then_branch, else_branch)
    def parse_for(self):
        self.consume('FOR')
        var_tok=self.consume('IDENT')
        var=var_tok.val if var_tok else 'i'
        self.consume('IN')
        iterable=self.parse_expr()
        self.consume('DO')
        body=[]
        while not self.at_end() and self.peek().typ!='END':
            s=self.parse_stmt()
            if s: body.append(s)
        self.consume('END')
        return ('for', var, iterable, body)
    def parse_while(self):
        self.consume('WHILE')
        cond=self.parse_expr()
        self.consume('DO')
        body=[]
        while not self.at_end() and self.peek().typ!='END':
            s=self.parse_stmt()
            if s: body.append(s)
        self.consume('END')
        return ('while', cond, body)
    def parse_return(self):
        self.consume('RETURN')
        if not self.at_end() and self.peek().typ not in ('END','ELSE','SEMI','RBRACE'):
            expr=self.parse_expr()
            return ('return', expr)
        else:
            return ('return', None)
    def parse_command_block(self):
        # Handles { ... }, ${ ... }, &{ ... }
        start=self.consume()
        typ=start.typ
        # Gather command nodes
        # For simplicity, parse commands as list of pipelines
        cmds=[]
        current_pipeline=[]
        current_cmd_parts=[]
        # Helper to flush current command
        def flush_cmd():
            nonlocal current_cmd_parts, current_pipeline
            if current_cmd_parts:
                current_pipeline.append(current_cmd_parts)
                current_cmd_parts=[]
        def flush_pipeline():
            nonlocal current_pipeline, cmds
            flush_cmd()
            if current_pipeline:
                cmds.append(current_pipeline)
                current_pipeline=[]
        while not self.at_end() and self.peek().typ!='RBRACE':
            tok=self.peek()
            if tok.typ=='SEMI':
                flush_pipeline()
                self.consume('SEMI')
                continue
            if tok.typ=='PIPE':
                flush_cmd()
                self.consume('PIPE')
                continue
            if tok.typ in ('WORD','STRING','CHAR','CMD_VAR','IDENT','AT_LBRACK','LBRACK','LPAREN','INT','FLOAT'):
                # For command words, treat WORD etc as word
                # For redirections: > < >> << etc are handled separately
                # Check if next is redirection?
                self.consume()
                current_cmd_parts.append(tok)
                continue
            if tok.typ in ('GT','LT','LTLT','GTGT'):
                # redirection operator
                op=self.consume()
                # Next token may be WORD or STRING or CMD_VAR or number?
                # For 2> etc, the previous token was '2' as INT? But we handled '2' as INT token? In command mode, '2' is WORD? Actually for "2>&1", lex gave tokens "2", ">", "&1"
                # So for redirection with fd, the fd is separate token before operator
                # Our parsing currently lumps fd as previous word? The current_cmd_parts may have last part as fd.
                # We'll treat redirection as part of current command: include operator and target
                # Consume target
                if not self.at_end():
                    tgt=self.peek()
                    # Target could be WORD or STRING or CMD_VAR or digits
                    if tgt.typ in ('WORD','STRING','CHAR','CMD_VAR','IDENT','INT'):
                        self.consume()
                        current_cmd_parts.append(op)
                        current_cmd_parts.append(tgt)
                    else:
                        current_cmd_parts.append(op)
                else:
                    current_cmd_parts.append(op)
                continue
            if tok.typ in ('GT','LT'):
                # already handled?
                self.consume()
                continue
            if tok.typ=='WORD' or tok.typ=='STRING':
                self.consume()
                current_cmd_parts.append(tok)
                continue
            # For digit redirection like "2" then ">" then "&1": the "2" would have been consumed as WORD/INT before, then ">" handles
            # So we need to handle standalone '>' etc
            # For simplicity, just consume unknown
            self.consume()
            current_cmd_parts.append(tok)
        # Expect closing }
        if not self.at_end() and self.peek().typ=='RBRACE':
            self.consume('RBRACE')
        flush_pipeline()
        if typ=='LBRACE':
            return ('cmd', cmds)
        elif typ=='DOLLAR_LBRACE':
            return ('capture', cmds)
        elif typ=='AMP_LBRACE':
            return ('async', cmds)
        else:
            return ('cmd', cmds)

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left=self.parse_and()
        while not self.at_end() and self.peek().typ=='OR':
            self.consume('OR')
            right=self.parse_and()
            left=('binop','or',left,right)
        return left
    def parse_and(self):
        left=self.parse_comparison()
        while not self.at_end() and self.peek().typ=='AND':
            self.consume('AND')
            right=self.parse_comparison()
            left=('binop','and',left,right)
        return left
    def parse_comparison(self):
        left=self.parse_concat()
        while not self.at_end() and self.peek().typ in ('EQEQ','NEQ','LTE','GTE','LT','GT'):
            op=self.consume()
            mapping={'EQEQ':'==','NEQ':'!=','LTE':'<=','GTE':'>=','LT':'<','GT':'>'}
            right=self.parse_concat()
            left=('binop',mapping[op.typ],left,right)
        return left
    def parse_concat(self):
        left=self.parse_add()
        while not self.at_end() and self.peek().typ=='PLUSPLUS':
            self.consume('PLUSPLUS')
            right=self.parse_add()
            left=('binop','++',left,right)
        return left
    def parse_add(self):
        left=self.parse_mul()
        while not self.at_end() and self.peek().typ in ('PLUS','MINUS'):
            op=self.consume()
            right=self.parse_mul()
            left=('binop',op.val,left,right)
        return left
    def parse_mul(self):
        left=self.parse_unary()
