    def parse_primary(self):
        if self.at_end():
            self.error(None, "unexpected end of file")
            return ('nil',)
        tok=self.peek()
        if tok.typ=='INT':
            self.consume('INT')
            return ('int',tok.val)
        if tok.typ=='FLOAT':
            self.consume('FLOAT')
            return ('float',tok.val)
        if tok.typ=='STRING':
            self.consume('STRING')
            return ('string',tok.val)
        if tok.typ=='CHAR':
            self.consume('CHAR')
            return ('char',tok.val)
        if tok.typ=='NIL':
            self.consume('NIL')
            return ('nil',)
        if tok.typ=='TRUE':
            self.consume('TRUE')
            return ('bool',True)
        if tok.typ=='FALSE':
            self.consume('FALSE')
            return ('bool',False)
        if tok.typ=='IDENT':
            self.consume('IDENT')
            return ('var',tok.val, tok.line, tok.col)
        if tok.typ=='SELF':
            self.consume('SELF')
            return ('self',)
        if tok.typ=='LPAREN':
            self.consume('LPAREN')
            expr=self.parse_expr()
            self.consume('RPAREN')
            return expr
        if tok.typ=='LBRACK':
            self.consume('LBRACK')
            elems=[]
            while not self.at_end() and self.peek().typ!='RBRACK':
                elems.append(self.parse_expr())
                if not self.at_end() and self.peek().typ=='COMMA':
                    self.consume('COMMA')
                else:
                    break
            self.consume('RBRACK')
            return ('array', elems)
        if tok.typ=='AT_LBRACK':
            self.consume('AT_LBRACK')
            pairs=[]
            while not self.at_end() and self.peek().typ!='RBRACK':
                # key: IDENT ':' expr or '[' expr ']' ':' expr ?
                key=None
                if self.peek().typ=='IDENT' and self.pos+1<len(self.tokens) and self.tokens[self.pos+1].typ=='COLON':
                    k=self.consume('IDENT')
                    self.consume('COLON')
                    key=k.val
                else:
                    # maybe string key? but hush dict keys are ident only
                    k=self.parse_expr()
                    self.consume('COLON')
                    # if k is string? treat as string key
                    if k[0]=='string':
                        key=k[1]
                    else:
                        key=str(k)
                val=self.parse_expr()
                pairs.append((key,val))
                if not self.at_end() and self.peek().typ=='COMMA':
                    self.consume('COMMA')
                else:
                    break
            self.consume('RBRACK')
            return ('dict', pairs)
        if tok.typ=='FUNCTION':
            self.consume('FUNCTION')
            self.consume('LPAREN')
            params=[]
            while not self.at_end() and self.peek().typ!='RPAREN':
                if self.peek().typ=='IDENT':
                    p=self.consume('IDENT')
                    params.append(p.val)
                # skip comma
                if not self.at_end() and self.peek().typ=='COMMA':
                    self.consume('COMMA')
                else:
                    break
            self.consume('RPAREN')
            body=[]
            while not self.at_end() and self.peek().typ!='END':
                s=self.parse_stmt()
                if s:
                    body.append(s)
            self.consume('END')
            return ('function', params, body)
        if tok.typ=='IF':
            self.consume('IF')
            cond=self.parse_expr()
            self.consume('THEN')
            then_branch=[]
            while not self.at_end() and self.peek().typ not in ('ELSE','END'):
                s=self.parse_stmt()
                if s: then_branch.append(s)
            else_branch=None
            if not self.at_end() and self.peek().typ=='ELSE':
                self.consume('ELSE')
                else_branch=[]
                while not self.at_end() and self.peek().typ!='END':
                    s=self.parse_stmt()
                    if s: else_branch.append(s)
            self.consume('END')
            return ('if_expr', cond, then_branch, else_branch)
        if tok.typ in ('LBRACE','DOLLAR_LBRACE','AMP_LBRACE'):
            # command block as expression?
            # For expression context, ${ ... } can be value, &{ ... } can be value
            # LBRACE as expression? Not typical, but handle
            return self.parse_command_block()
        # unknown
        self.error(tok, f"unexpected '{tok.raw}'")
        self.consume()
        return ('nil',)

def ast_to_string(node):
    # Convert AST node to string as per original --ast output
    if node is None:
        return ""
    typ=node[0]
    if typ=='let':
        _, var, expr, line, col = node
        if expr is None:
            return f"let {var} = nil"
        else:
            return f"let {var} = {expr_to_string(expr)}"
    if typ=='assign':
        _, var, expr, line, col = node
        return f"{var} = {expr_to_string(expr)}"
    if typ=='expr':
        return expr_to_string(node[1])
    if typ=='if':
        _, cond, then_branch, else_branch = node
        s=f"if {expr_to_string(cond)} then\n"
        for stmt in then_branch:
            s+= f"\t{ast_to_string(stmt)}\n"
        if else_branch is not None:
            s+= "else\n"
            for stmt in else_branch:
                s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ=='for':
        _, var, iterable, body = node
        s=f"for {var} in {expr_to_string(iterable)} do\n"
        for stmt in body:
            s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ=='while':
        _, cond, body = node
        s=f"while {expr_to_string(cond)} do\n"
        for stmt in body:
            s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ=='break':
        return "break"
    if typ=='return':
        _, expr = node
        if expr is None:
            return "return"
        else:
            return f"return {expr_to_string(expr)}"
    if typ in ('cmd','capture','async'):
        return cmd_to_string(node)
    return str(node)

def expr_to_string(node):
    if node is None:
        return "nil"
    typ=node[0]
    if typ=='int':
        return str(node[1])
    if typ=='float':
        v=node[1]
        # format to preserve? For 1.5 etc
        if isinstance(v,float):
            # remove trailing zeros? Original prints "1.5" etc, "890000000000" for 89e10?
            # For float, they printed as integer without .0 if it came from exponent? In AST, float from 89e10 was expanded to 890000000000 (no decimal). Our expr value is original float expanded? We'll use string of int if integer valued?
            if v.is_integer():
                # Check if original was exponent case: we lost info, but okay to print without decimal for integer-valued floats? In prior test, 1.2e3 gave 1200 not 1200.0 in lex, but in AST/ program, 1.2e3 was 1200 (int) as well. So we can print as int string.
                return str(int(v))
            else:
                # Need to preserve .5 etc
                # Use repr removing trailing?
                s=str(v)
                return s
        else:
            return str(v)
    if typ=='string':
        # Escape string for display: wrap in double quotes, escape \n etc?
        # Original string display escapes \n as \n? In lex we saw "hello \n world" displayed with \n.
        # In AST, string "hello" shows as "\"hello\""
        # For string value containing \n, original AST for "escape \n sequences" showed "\"escape \\n sequences \\\" are ...\""
        # So need to escape: \n -> \\n, \t -> \\t, \" -> \\\", \\ -> \\\\, \0 -> \\0
        s=node[1]
        esc=s.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\t','\\t').replace('\0','\\0')
        return f'"{esc}"'
    if typ=='char':
        v=node[1]
        # char display as '\'a\'' ?
        if v=='\n':
            esc='\\n'
        elif v=='\t':
            esc='\\t'
        elif v=="'":
            esc="\\'"
        elif v=='"':
            esc='\\"'
        elif v=='\\':
            esc='\\\\'
        elif v=='\0':
            esc='\\0'
        else:
            esc=v
        return f"'{esc}'"
    if typ=='nil':
        return "nil"
    if typ=='bool':
        return "true" if node[1] else "false"
    if typ=='var':
        return node[1]
    if typ=='self':
        return "self"
    if typ=='array':
        elems=node[1]
        if not elems:
            return "[ ]"
        inner=", ".join(expr_to_string(e) for e in elems)
        # Original prints [
        #   1,
        #   2
        # ]
        # For single line, they collapse? In AST sample, [1,2,3] prints as "[\n\t1,\n\t2,\n\t3\n]"
        # We'll just print as "[ 1, 2, 3 ]" for simplicity but need to match exactly.
        # For now, try to match original multiline for arrays with multiple elements?
        # We'll produce multiline if len>1?
        if len(elems)>1:
            parts=",\n\t".join(expr_to_string(e) for e in elems)
            return f"[\n\t{parts}\n]"
        else:
            return f"[ {inner} ]"
    if typ=='dict':
        pairs=node[1]
        if not pairs:
            return "@[ ]"
        lines=[]
        for k,v in pairs:
            lines.append(f"\t{k}: {expr_to_string(v)}")
        return "@[\n"+",\n".join(lines)+"\n]"
    if typ=='binop':
        _, op, left, right = node
        return f"({expr_to_string(left)} {op} {expr_to_string(right)})"
    if typ=='unop':
        _, op, expr = node
        if op=='not':
            return f"(not {expr_to_string(expr)})"
        else:
            return f"(- {expr_to_string(expr)})"
    if typ=='dot':
        _, obj, field, line, col = node
        return f"{expr_to_string(obj)}.{field}"
    if typ=='index':
        _, obj, idx = node
        return f"{expr_to_string(obj)}[{expr_to_string(idx)}]"
    if typ=='call':
        _, func, args = node
        args_str=", ".join(expr_to_string(a) for a in args)
        return f"{expr_to_string(func)}({args_str})"
    if typ=='function':
        _, params, body = node
        s=f"function({', '.join(params)})\n"
        for stmt in body:
            s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ=='if_expr':
        _, cond, then_branch, else_branch = node
        s=f"if {expr_to_string(cond)} then\n"
        for stmt in then_branch:
            s+= f"\t{ast_to_string(stmt)}\n"
        if else_branch is not None:
            s+= "else\n"
            for stmt in else_branch:
                s+= f"\t{ast_to_string(stmt)}\n"
        s+= "end"
        return s
    if typ in ('cmd','capture','async'):
        return cmd_to_string(node)
    return str(node)

def cmd_to_string(node):
    typ=node[0]
    cmds=node[1]
    # cmds is list of pipelines, each pipeline is list of commands, each command is list of tokens
    # For AST, they print as:
    # {
    #     "echo" "hi"
    # }
    # For pipelines: "echo" "hi" | "cat"
    # For with redirections: "echo" "hi" 1>"file"
    # We'll reconstruct
    if not cmds:
        return "{ ***ill-formed*** ? }"
    lines=[]
    for pipeline in cmds:
        # pipeline is list of commands (each command is list of tokens)
        # For simplicity, we have cmds as list of pipelines where each pipeline is list of command parts? In parser, we built cmds as list of pipelines, but current structure is: cmds = list of pipelines, each pipeline is list of command token lists.
        # However our parser built cmds as list of pipelines where each pipeline appended current_pipeline which is list of command token lists.
        # Example: "echo hi | cat" => cmds = [[ [WORD echo, WORD hi], [WORD cat] ]]
        # For "{ echo hi }", cmds = [ [ [echo, hi] ] ] -> one pipeline with one command
        # We'll handle both cases where pipeline may be flat
        if not pipeline:
            continue
        # If pipeline is list of command token lists, join with " | "
        cmd_strs=[]
        for cmd_tokens in pipeline:
            # cmd_tokens is list of Token
            parts=[]
            for tok in cmd_tokens:
                if tok.typ=='WORD':
                    # quote word as "word"
                    parts.append(f'"{tok.val}"')
                elif tok.typ=='STRING':
                    # STRING token's val already decoded, need to re-escape for display as "string"
                    s=tok.val
                    # s may contain placeholder ${{...}}; for display, we need to quote placeholder as "${{...}}" ?
                    # For command string "\"hello ${{x}}\"", we want "\"hello ${{x}}\""
                    # Our STRING val contains placeholder, we can display as original raw? Use raw
                    # Use token.raw for display
                    parts.append(f'"{tok.raw[1:-1]}"' if tok.raw.startswith('"') else f'"{tok.val}"')
                    # Simplify: use raw
                    parts[-1]=f'"{tok.raw[1:-1]}"' if len(tok.raw)>=2 else '""'
                elif tok.typ=='CHAR':
                    # CHAR raw is like "'a'"
                    parts.append(tok.raw)
                elif tok.typ=='CMD_VAR':
                    # display as "${{var}}"
                    parts.append(f'"${{{tok.val}}}"')  # Actually displayed as "${{x}}" without quotes? In lex, CMD_VAR inside command is "${{x}}" (without quotes)
                    # For AST, they display as "\"${{x}}\""? Let's check: earlier AST for { echo $x } was not tested. For ${ echo $x }, AST showed "echo" "${args}" ?
                    # In AST for `let error = ${ echo $args }`, AST was "echo" "${args}" (quoted)
                    parts[-1]=f'"${{{tok.val}}}"' if tok.typ=='CMD_VAR' else parts[-1]
                    # Actually better to keep as quoted string for AST
                elif tok.typ in ('GT','LT','LTLT','GTGT','PIPE','SEMI'):
                    parts.append(tok.raw)
                else:
                    parts.append(tok.raw)
            cmd_strs.append(" ".join(parts))
        lines.append(" | ".join(cmd_strs))
    # Now produce final block
    if typ=='LBRACE' or typ=='cmd':
        # original prints {
        # \t"echo" "hi"
        # }
        inner="\n".join(f"\t{line}" for line in lines)
        return "{\n" + inner + "\n}"
    elif typ=='capture': # ${ ... }
        inner="\n".join(f"\t{line}" for line in lines)
        return "${\n" + inner + "\n}"
    elif typ=='async': # &{ ... }
        inner="\n".join(f"\t{line}" for line in lines)
        return "&{\n" + inner + "\n}"
    else:
        inner="\n".join(lines)
        return inner

