            break
        if flag_mode and a.startswith('-'):
            if a=='--lex':
                flags['lex']=True
            elif a=='--ast':
                flags['ast']=True
            elif a=='--program':
                flags['program']=True
            elif a=='--check':
                flags['check']=True
            elif a in ('-h','--help'):
