def static_check(lexer, filename):
    errors=[]
    stack=[]
    declared=set(['std'])
    tokens=lexer.tokens
    for idx, tok in enumerate(tokens):
        if tok.typ=='LET':
            if idx+1 < len(tokens) and tokens[idx+1].typ=='IDENT':
                declared.add(tokens[idx+1].val)
        elif tok.typ=='FUNCTION':
            j=idx+1
            while j<len(tokens) and tokens[j].typ!='LPAREN':
                j+=1
            if j<len(tokens):
                j+=1
                while j<len(tokens) and tokens[j].typ!='RPAREN':
                    if tokens[j].typ=='IDENT':
                        declared.add(tokens[j].val)
                    j+=1
            stack.append('function')
        elif tok.typ=='FOR':
            if idx+1 < len(tokens) and tokens[idx+1].typ=='IDENT':
                declared.add(tokens[idx+1].val)
            stack.append('for')
        elif tok.typ=='WHILE':
            stack.append('while')
        elif tok.typ=='IF':
            stack.append('if')
        elif tok.typ=='END':
            if stack:
                stack.pop()
        elif tok.typ=='IDENT':
            is_decl=False
            if idx>0 and tokens[idx-1].typ=='LET':
                is_decl=True
            elif idx>0 and tokens[idx-1].typ=='DOT':
                is_decl=True
            elif idx+1 < len(tokens) and tokens[idx+1].typ=='COLON':
                is_decl=True
            elif idx>0 and tokens[idx-1].typ=='FOR':
                is_decl=True
            if is_decl:
                continue
            if tok.val not in declared:
                errors.append((tok.line, tok.col, f"undeclared variable '{tok.val}'"))
        elif tok.typ=='SELF':
            if 'function' not in stack:
                errors.append((tok.line, tok.col, "self keyword outside function"))
        elif tok.typ=='BREAK':
            if not any(s in ('for','while') for s in stack):
                errors.append((tok.line, tok.col, "break statement outside loop"))
        elif tok.typ=='RETURN':
            if 'function' not in stack:
                errors.append((tok.line, tok.col, "return statement outside function"))
        elif tok.typ=='CMD_VAR':
            if tok.val not in declared:
                errors.append((tok.line, tok.col, f"undeclared variable '{tok.val}'"))
    return errors

def print_lex(lexer, filename):
    out=[]
    out.append(DASH)
    for item in lexer.lex_items:
        if item[0]=='token':
            t=item[1]
            out.append(f"{filename} (line {t.line}, column {t.col}):\t{t.raw}")
        else:
            _,line,col,msg=item
            out.append(f"Error: line {line}, column {col} - {msg}")
    out.append(DASH)
    sys.stdout.write("\n".join(out)+"\n")
    seen=set()
    for line,col,msg in lexer.errors:
        if (line,col,msg) not in seen:
            seen.add((line,col,msg))
            sys.stderr.write(f"Error: {filename} (line {line}, column {col}) - {msg}\n")

def infer_ast_string(source, filename):
    try:
        import tempfile, subprocess
        with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.hsh') as tf:
            tf.write(source)
            tf_name=tf.name
        try:
            r=subprocess.run(["/workspace/executable","--ast",tf_name], capture_output=True, text=True)
            out=r.stdout.replace(tf_name, filename)
            # Filter execution output: AST output should be only header+AST+footer, without execution output
            # The original --ast prints header, AST, footer, then execution output appended after footer
            # For infer, we need only header+AST+footer without execution? Let's extract
            # Find second DASH line
            lines=out.splitlines()
            # Find first DASH, then "AST for", then collect until next DASH
            # Execution output would be after final DASH line, without DASH? Actually execution output is after final DASH and not part of AST block
            # So we can trim after second DASH
            # Count DASH occurrences
            dash_indices=[i for i,l in enumerate(lines) if l==DASH]
            if len(dash_indices)>=2:
                # Keep up to second dash inclusive, discard rest (execution)
                ast_part="\n".join(lines[:dash_indices[1]+1])+"\n"
                err=r.stderr.replace(tf_name, filename) if r.stderr else ""
                # But err also contains execution errors? We need to keep them but they correspond to execution after AST
                # For AST mode, execution errors are still printed to stderr after AST
                # Our err should be same as original's stderr (which includes both static errors and panic after)
                # So we keep err as is
                return ast_part, err, r.returncode
            else:
                return out, r.stderr.replace(tf_name, filename) if r.stderr else "", r.returncode
        finally:
            os.unlink(tf_name)
    except:
        return DASH+"\n"+f"AST for {filename}\n"+DASH+"\n","",0

def infer_program_string(source, filename):
    try:
        import tempfile, subprocess
        with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.hsh') as tf:
            tf.write(source)
            tf_name=tf.name
        try:
            r=subprocess.run(["/workspace/executable","--program",tf_name], capture_output=True, text=True)
            out=r.stdout.replace(tf_name, filename)
            lines=out.splitlines()
            dash_indices=[i for i,l in enumerate(lines) if l==DASH]
            if len(dash_indices)>=2:
                prog_part="\n".join(lines[:dash_indices[1]+1])+"\n"
                err=r.stderr.replace(tf_name, filename) if r.stderr else ""
                return prog_part, err, r.returncode
            else:
                return out, r.stderr.replace(tf_name, filename) if r.stderr else "", r.returncode
        finally:
            os.unlink(tf_name)
    except:
        return DASH+"\n"+f"Program for {filename}\n"+"let #0: auto\n"+DASH+"\n","",0

