            ch=self.peek()
            if ch=='"':
                self.advance()
                raw.append('"')
                break
            if ch=='\\':
                esc_col=self.col
                self.advance()
                if self.pos>=self.n:
                    self.err_inline(line,esc_col,"invalid escape sequence '\\'.")
                    buf.append('\\')
                    raw.append('\\')
                    break
                esc=self.peek()
                self.advance()
                raw.append('\\'+esc)
                if esc=='n':
                    buf.append('\n')
                elif esc=='t':
                    buf.append('\t')
                elif esc=='"':
                    buf.append('"')
                elif esc=="'":
                    buf.append("'")
                elif esc=='\\':
                    buf.append('\\')
                elif esc=='0':
                    buf.append('\0')
                else:
                    self.err_inline(line,esc_col,f"invalid escape sequence '\\{esc}'.")
                    buf.append('\0')
                continue
            if ch=='\n':
                self.err(line,col,"unterminated string")
                break
            if inside and ch=='$':
                nxt=self.peek(1)
                if nxt=='{':
                    self.advance(); self.advance()
                    ident=''
                    while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                        ident+=self.peek(); self.advance()
                    if self.pos<self.n and self.peek()=='}':
                        self.advance()
                        placeholder='${{'+ident+'}}'
                        buf.append(placeholder)
                        raw.append(placeholder)
                    else:
                        self.err_inline(line,col,"unterminated variable")
                    continue
                elif nxt.isalpha() or nxt=='_':
                    self.advance()
                    ident=''
                    while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                        ident+=self.peek(); self.advance()
                    placeholder='${{'+ident+'}}'
                    buf.append(placeholder)
                    raw.append(placeholder)
                    continue
                else:
                    buf.append('$')
                    raw.append('$')
                    self.advance()
                    continue
            else:
                buf.append(ch)
                raw.append(ch)
                self.advance()
