        if self.pos>=self.n:
            self.err(line,col,"unterminated char")
            return
        ch=self.peek()
        if ch=='\\':
            esc_col=self.col
            self.advance()
            if self.pos>=self.n:
                self.err(line,col,"invalid escape")
                return
            esc=self.peek()
            self.advance()
            if esc not in ('n','t','"',"'" ,'\\','0'):
                self.err_inline(line,esc_col,f"invalid escape sequence '\\{esc}'.")
                val='\0'
                raw="'\\0'"
            else:
                if esc=='n':
                    val='\n'
                elif esc=='t':
                    val='\t'
                elif esc=='"':
                    val='"'
                elif esc=="'":
                    val="'"
                elif esc=='\\':
                    val='\\'
                elif esc=='0':
