                    num_str+=self.peek()
                    self.advance()
        raw=num_str
        norm=raw
        try:
            if 'e' in raw.lower():
                mant,exp = raw.lower().split('e')
                mant_val=float(mant)
                exp_val=int(exp)
                val=mant_val*(10**exp_val)
                if float(val).is_integer():
                    norm=str(int(val))
                else:
                    norm=str(val)
                    if norm.endswith('.0'):
