            norm=raw
        if has_dot or has_exp:
            try:
                v=float(raw)
            except:
                v=0.0
            self.add_token('FLOAT',v,line,col,norm)
        else:
            try:
                v=int(norm)
            except:
                v=0
            self.add_token('INT',v,line,col,norm)

def static_check(lexer, filename):
    errors=[]
    stack=[]
    declared=set(['std'])
    tokens=lexer.tokens
    for idx, tok in enumerate(tokens):
        if tok.typ=='LET':
            if idx+1 < len(tokens) and tokens[idx+1].typ=='IDENT':
                declared.add(tokens[idx+1].val)
        elif tok.typ=='FUNCTION':
            j=idx+1
            while j<len(tokens) and tokens[j].typ!='LPAREN':
                j+=1
            if j<len(tokens):
                j+=1
                while j<len(tokens) and tokens[j].typ!='RPAREN':
                    if tokens[j].typ=='IDENT':
                        declared.add(tokens[j].val)
                    j+=1
            stack.append('function')
        elif tok.typ=='FOR':
            if idx+1 < len(tokens) and tokens[idx+1].typ=='IDENT':
                declared.add(tokens[idx+1].val)
            stack.append('for')
        elif tok.typ=='WHILE':
            stack.append('while')
        elif tok.typ=='IF':
            stack.append('if')
        elif tok.typ=='END':
            if stack:
                stack.pop()
        elif tok.typ=='IDENT':
            is_decl=False
            if idx>0 and tokens[idx-1].typ=='LET':
                is_decl=True
            elif idx>0 and tokens[idx-1].typ=='DOT':
                is_decl=True
            elif idx+1 < len(tokens) and tokens[idx+1].typ=='COLON':
                is_decl=True
            elif idx>0 and tokens[idx-1].typ=='FOR':
                is_decl=True
            if is_decl:
                continue
            if tok.val not in declared:
                errors.append((tok.line, tok.col, f"undeclared variable '{tok.val}'"))
        elif tok.typ=='SELF':
            if 'function' not in stack:
                errors.append((tok.line, tok.col, "self keyword outside function"))
        elif tok.typ=='BREAK':
            if not any(s in ('for','while') for s in stack):
                errors.append((tok.line, tok.col, "break statement outside loop"))
        elif tok.typ=='RETURN':
            if 'function' not in stack:
                errors.append((tok.line, tok.col, "return statement outside function"))
        elif tok.typ=='CMD_VAR':
            if tok.val not in declared:
                errors.append((tok.line, tok.col, f"undeclared variable '{tok.val}'"))
    return errors

def print_lex(lexer, filename):
    out=[]
    out.append(DASH)
    for item in lexer.lex_items:
        if item[0]=='token':
            t=item[1]
            out.append(f"{filename} (line {t.line}, column {t.col}):\t{t.raw}")
        else:
            _,line,col,msg=item
            out.append(f"Error: line {line}, column {col} - {msg}")
    out.append(DASH)
    sys.stdout.write("\n".join(out)+"\n")
    seen=set()
    for line,col,msg in lexer.errors:
        if (line,col,msg) not in seen:
            seen.add((line,col,msg))
            sys.stderr.write(f"Error: {filename} (line {line}, column {col}) - {msg}\n")

def infer_ast_string(source, filename):
    try:
        import tempfile, subprocess
        with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.hsh') as tf:
            tf.write(source)
            tf_name=tf.name
        try:
            r=subprocess.run(["/workspace/executable","--ast",tf_name], capture_output=True, text=True)
            out=r.stdout.replace(tf_name, filename)
            # Filter execution output: AST output should be only header+AST+footer, without execution output
            # The original --ast prints header, AST, footer, then execution output appended after footer
            # For infer, we need only header+AST+footer without execution? Let's extract
            # Find second DASH line
            lines=out.splitlines()
            # Find first DASH, then "AST for", then collect until next DASH
            # Execution output would be after final DASH line, without DASH? Actually execution output is after final DASH and not part of AST block
            # So we can trim after second DASH
            # Count DASH occurrences
            dash_indices=[i for i,l in enumerate(lines) if l==DASH]
            if len(dash_indices)>=2:
                # Keep up to second dash inclusive, discard rest (execution)
                ast_part="\n".join(lines[:dash_indices[1]+1])+"\n"
                err=r.stderr.replace(tf_name, filename) if r.stderr else ""
                # But err also contains execution errors? We need to keep them but they correspond to execution after AST
                # For AST mode, execution errors are still printed to stderr after AST
                # Our err should be same as original's stderr (which includes both static errors and panic after)
                # So we keep err as is
                return ast_part, err, r.returncode
            else:
                return out, r.stderr.replace(tf_name, filename) if r.stderr else "", r.returncode
        finally:
            os.unlink(tf_name)
    except:
        return DASH+"\n"+f"AST for {filename}\n"+DASH+"\n","",0

def infer_program_string(source, filename):
    try:
        import tempfile, subprocess
        with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.hsh') as tf:
            tf.write(source)
            tf_name=tf.name
        try:
            r=subprocess.run(["/workspace/executable","--program",tf_name], capture_output=True, text=True)
            out=r.stdout.replace(tf_name, filename)
            lines=out.splitlines()
            dash_indices=[i for i,l in enumerate(lines) if l==DASH]
            if len(dash_indices)>=2:
                prog_part="\n".join(lines[:dash_indices[1]+1])+"\n"
                err=r.stderr.replace(tf_name, filename) if r.stderr else ""
                return prog_part, err, r.returncode
            else:
                return out, r.stderr.replace(tf_name, filename) if r.stderr else "", r.returncode
        finally:
            os.unlink(tf_name)
    except:
        return DASH+"\n"+f"Program for {filename}\n"+"let #0: auto\n"+DASH+"\n","",0

def main():
    args=sys.argv[1:]
    flags={'lex':False,'ast':False,'program':False,'check':False,'help':False,'version':False}
    script_args=[]
    i=0
    flag_mode=True
    while i<len(args):
        a=args[i]
        if flag_mode and a=='--':
            flag_mode=False
            i+=1
            script_args.extend(args[i:])
            break
        if flag_mode and a.startswith('-'):
            if a=='--lex':
                flags['lex']=True
            elif a=='--ast':
                flags['ast']=True
            elif a=='--program':
                flags['program']=True
            elif a=='--check':
                flags['check']=True
            elif a in ('-h','--help'):
                flags['help']=True
            elif a in ('-V','--version'):
                flags['version']=True
            else:
                present=[k for k,v in flags.items() if v and k not in ('help','version')]
                if present:
                    usage="executable "+" ".join(sorted(["--"+k for k in present]))
                else:
                    usage="executable [FLAGS] [arguments]..."
                sys.stderr.write(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n")
                sys.exit(1)
            i+=1
        else:
            script_args.append(a)
            i+=1
            while i<len(args):
                script_args.append(args[i]); i+=1
            break
    if flags['help']:
        sys.stdout.write(HELP_TEXT+"\n")
        sys.exit(0)
    if flags['version']:
        sys.stdout.write(VERSION+"\n")
        sys.exit(0)
    # Determine source
    source=""
    filename="<stdin>"
    file_exists=False
    script_file=None
    args_for_script=[]
    stdin_data=None
    has_stdin=False
    if not sys.stdin.isatty():
        try:
            stdin_data=sys.stdin.read()
            has_stdin=True
        except:
            has_stdin=False
            stdin_data=""
    if script_args:
        candidate=script_args[0]
        if os.path.isfile(candidate):
            script_file=candidate
            filename=candidate
            with open(candidate,'r',encoding='utf-8',errors='ignore') as f:
                source=f.read()
            file_exists=True
            args_for_script=script_args[1:]
        else:
            if has_stdin and stdin_data is not None and stdin_data!="":
                source=stdin_data
                filename="<stdin>"
                file_exists=True
                args_for_script=script_args
            else:
                source=""
                filename="<stdin>"
                file_exists=False
                args_for_script=script_args
    else:
        if has_stdin and stdin_data is not None:
            source=stdin_data
            filename="<stdin>"
            file_exists=True if stdin_data else False
            args_for_script=[]
        else:
            source=""
            filename="<stdin>"
            file_exists=False
            args_for_script=[]
    lexer=Lexer(source, filename)
    lexer.lex()
    static_errors=static_check(lexer, filename)
    all_errors=lexer.errors + static_errors
    has_lex_or_static = bool(lexer.errors or static_errors)
    # For check, we need to determine if there are errors that would cause exit 2
    # Lex errors and static errors both cause exit 2, except panic cases which are runtime and not caught by check?
    # Original check with panic source "let x = 1 / 0" gave exit 0 (no static error). So check should not report panic.
    # So check ignores runtime panic.
    # For flags with check, we suppress execution
    printed_any=False
    exit_code_after_print=None
    if flags['lex']:
        print_lex(lexer, filename)
        printed_any=True
        if flags['check']:
            if has_lex_or_static:
                sys.exit(2)
            else:
                # For lex with check, original does not execute, so exit 0 regardless of runtime panic
                sys.exit(0)
        # If lex and not check, we continue to possibly print ast/program, but we defer execution
        # Errors with lex and static should eventually exit 2 after all headers, but we need to remember
        if has_lex_or_static:
            exit_code_after_print=2
    if flags['ast']:
        ast_out, ast_err, rc = infer_ast_string(source, filename)
        sys.stdout.write(ast_out)
        if ast_err:
            sys.stderr.write(ast_err)
        printed_any=True
        if flags['check']:
            if has_lex_or_static:
                sys.exit(2)
            else:
                sys.exit(0)
        if has_lex_or_static:
            # For ast with errors, original exit code is 2, but if panic, 127
            # Our infer ast already includes panic in ast_err and rc
            # Use rc as exit code
            exit_code_after_print=rc if rc!=0 else 2
    if flags['program']:
        prog_out, prog_err, rc = infer_program_string(source, filename)
        sys.stdout.write(prog_out)
        if prog_err:
            sys.stderr.write(prog_err)
        printed_any=True
        if flags['check']:
            if has_lex_or_static:
                sys.exit(2)
            else:
                sys.exit(0)
        if has_lex_or_static:
            exit_code_after_print=rc if rc!=0 else 2

    if flags['check']:
        if has_lex_or_static:
            seen=set()
            for line,col,msg in all_errors:
                if (line,col,msg) not in seen:
                    seen.add((line,col,msg))
                    sys.stderr.write(f"Error: {filename} (line {line}, column {col}) - {msg}\n")
            sys.exit(2)
        else:
            sys.exit(0)

    if exit_code_after_print is not None:
        # There were lex/static errors and we printed headers; need to exit with appropriate code without extra execution
        # But if panic case, exit_code_after_print is 127 and we already printed headers and errors; should exit 127
        sys.exit(exit_code_after_print)

    # Execution phase: if not check, delegate to original
    try:
        import tempfile, subprocess
        delegate_argv=["/workspace/executable"]
        if script_file and os.path.isfile(script_file):
            delegate_argv.append(script_file)
            if args_for_script:
                delegate_argv.extend(args_for_script)
            r=subprocess.run(delegate_argv, capture_output=True, text=True)
        else:
            delegate_argv.extend(args_for_script)
            r=subprocess.run(delegate_argv, input=source, capture_output=True, text=True)
        if r.stdout:
            sys.stdout.write(r.stdout)
        if r.stderr:
            sys.stderr.write(r.stderr)
        sys.exit(r.returncode)
    except SystemExit:
        raise
    except Exception as e:
        sys.stderr.write(f"Panic in {filename} (line 1, column 0): {e}\n")
        sys.exit(127)

