def main():
    args=sys.argv[1:]
    flags={'lex':False,'ast':False,'program':False,'check':False,'help':False,'version':False}
    script_args=[]
    i=0
    flag_mode=True
    while i<len(args):
        a=args[i]
        if flag_mode and a=='--':
            flag_mode=False
            i+=1
            script_args.extend(args[i:])
            break
        if flag_mode and a.startswith('-'):
            if a=='--lex':
                flags['lex']=True
            elif a=='--ast':
                flags['ast']=True
            elif a=='--program':
                flags['program']=True
            elif a=='--check':
                flags['check']=True
            elif a in ('-h','--help'):
                flags['help']=True
            elif a in ('-V','--version'):
                flags['version']=True
            else:
                present=[k for k,v in flags.items() if v and k not in ('help','version')]
                if present:
                    usage="executable "+" ".join(sorted(["--"+k for k in present]))
                else:
                    usage="executable [FLAGS] [arguments]..."
                sys.stderr.write(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n")
                sys.exit(1)
            i+=1
        else:
            script_args.append(a)
            i+=1
            while i<len(args):
                script_args.append(args[i]); i+=1
            break
    if flags['help']:
        sys.stdout.write(HELP_TEXT+"\n")
        sys.exit(0)
    if flags['version']:
        sys.stdout.write(VERSION+"\n")
        sys.exit(0)
    source=""
    filename="<stdin>"
    file_exists=False
    script_file=None
    args_for_script=[]
    stdin_data=None
    has_stdin=False
    if not sys.stdin.isatty():
        try:
            stdin_data=sys.stdin.read()
            has_stdin=True
        except:
            has_stdin=False
            stdin_data=""
    if script_args:
        candidate=script_args[0]
        if os.path.isfile(candidate):
            script_file=candidate
            filename=candidate
            with open(candidate,'r',encoding='utf-8',errors='ignore') as f:
                source=f.read()
            file_exists=True
            args_for_script=script_args[1:]
        else:
            if has_stdin and stdin_data is not None and stdin_data!="":
                source=stdin_data
                filename="<stdin>"
                file_exists=True
                args_for_script=script_args
            else:
                source=""
                filename="<stdin>"
                file_exists=False
                args_for_script=script_args
    else:
        if has_stdin and stdin_data is not None:
            source=stdin_data
            filename="<stdin>"
            file_exists=True if stdin_data else False
            args_for_script=[]
        else:
            source=""
            filename="<stdin>"
            file_exists=False
            args_for_script=[]
    lexer=Lexer(source, filename)
    lexer.lex()
    static_errors=static_check(lexer, filename)
    all_errors=lexer.errors + static_errors
    has_lex_or_static = bool(lexer.errors or static_errors)
    printed_any=False
    exit_code_after_print=None
    exec_out_buffer=""
    exec_err_buffer=""
    exec_rc_buffer=None
    if flags['lex']:
        print_lex(lexer, filename)
        printed_any=True
        if static_errors:
            seen=set()
            for line,col,msg in static_errors:
                if (line,col,msg) not in seen:
                    seen.add((line,col,msg))
                    sys.stderr.write(f"Error: {filename} (line {line}, column {col}) - {msg}\n")
        if flags['check']:
            if has_lex_or_static:
                sys.exit(2)
            else:
                sys.exit(0)
        if has_lex_or_static:
            exit_code_after_print=2
    if flags['ast']:
        ast_out, exec_out, ast_err, rc = infer_ast_string(source, filename, args_for_script)
        sys.stdout.write(ast_out)
        if exec_out:
            exec_out_buffer+=exec_out
        if ast_err:
            sys.stderr.write(ast_err)
            exec_err_buffer+=ast_err
            exec_rc_buffer=rc
        printed_any=True
        if flags['check']:
            if has_lex_or_static:
                sys.exit(2)
            else:
                sys.exit(0)
        if has_lex_or_static:
            exit_code_after_print=rc if rc!=0 else 2
    if flags['program']:
        prog_out, exec_out2, prog_err, rc = infer_program_string(source, filename, args_for_script)
        sys.stdout.write(prog_out)
        if exec_out2:
            exec_out_buffer+=exec_out2
        if prog_err:
            sys.stderr.write(prog_err)
            exec_err_buffer+=prog_err
            exec_rc_buffer=rc
        printed_any=True
        if flags['check']:
            if has_lex_or_static:
                sys.exit(2)
            else:
                sys.exit(0)
        if has_lex_or_static:
            exit_code_after_print=rc if rc!=0 else 2
    if flags['check']:
        if has_lex_or_static:
            seen=set()
            for line,col,msg in all_errors:
                if (line,col,msg) not in seen:
                    seen.add((line,col,msg))
                    sys.stderr.write(f"Error: {filename} (line {line}, column {col}) - {msg}\n")
            sys.exit(2)
        else:
            sys.exit(0)
    if exit_code_after_print is not None:
        sys.exit(exit_code_after_print)
    if printed_any:
        if exec_out_buffer or exec_err_buffer:
            if exec_out_buffer:
                sys.stdout.write(exec_out_buffer)
            if "Panic" in exec_err_buffer:
                sys.exit(127)
            else:
                sys.exit(0)
        else:
            if flags['lex'] and not flags['ast'] and not flags['program']:
                try:
                    delegate_argv=["/workspace/executable"]
                    if script_file and os.path.isfile(script_file):
                        delegate_argv.append(script_file)
                        if args_for_script:
                            delegate_argv.extend(args_for_script)
                        r=subprocess.run(delegate_argv, capture_output=True, text=True)
