    <arguments>...    Script and/or arguments"""

DASH="--------------------------------------------------"

class Token:
    __slots__=('typ','val','line','col','raw')
    def __init__(self,typ,val,line,col,raw):
        self.typ=typ
        self.val=val
        self.line=line
        self.col=col
        self.raw=raw

KEYWORDS={"let":"LET","if":"IF","then":"THEN","else":"ELSE","end":"END","for":"FOR","in":"IN","do":"DO","while":"WHILE","function":"FUNCTION","return":"RETURN","break":"BREAK","self":"SELF","nil":"NIL","true":"TRUE","false":"FALSE","or":"OR","and":"AND","not":"NOT"}

class Lexer:
    def __init__(self,src,filename):
        self.src=src
        self.filename=filename
        self.pos=0
        self.line=1
        self.col=0
        self.n=len(src)
        self.tokens=[]
        self.errors=[]
        self.lex_items=[]
        self.cmd_depth=0
    def peek(self,off=0):
        i=self.pos+off
        return self.src[i] if i<self.n else '\0'
    def advance(self):
        ch=self.src[self.pos]
        self.pos+=1
        if ch=='\n':
            self.line+=1
            self.col=0
        else:
            self.col+=1
        return ch
    def add_token(self,typ,val,line,col,raw):
        t=Token(typ,val,line,col,raw)
        self.tokens.append(t)
        self.lex_items.append(('token',t))
    def err_inline(self,line,col,msg):
        self.errors.append((line,col,msg))
        self.lex_items.append(('error',line,col,msg))
    def err(self,line,col,msg):
        self.errors.append((line,col,msg))
    def lex(self):
        if self.src.startswith("#!"):
            while self.pos<self.n and self.peek()!='\n':
                self.advance()
            if self.pos<self.n:
                self.advance()
        while self.pos<self.n:
            sl=self.line
            sc=self.col
            ch=self.peek()
            if ch in ' \t\r':
                self.advance(); continue
            if ch=='\n':
                self.advance(); continue
            if ch=='#':
                while self.pos<self.n and self.peek()!='\n':
                    self.advance()
                continue
            if ch=='$' and self.peek(1)=='{':
                self.advance(); self.advance()
                self.add_token('DOLLAR_LBRACE','${',sl,sc,'${')
                self.cmd_depth+=1
                continue
            if ch=='&' and self.peek(1)=='{':
                self.advance(); self.advance()
                self.add_token('AMP_LBRACE','&{',sl,sc,'&{')
                self.cmd_depth+=1
                continue
            if ch=='{':
                self.advance()
                self.add_token('LBRACE','{',sl,sc,'{')
                self.cmd_depth+=1
                continue
            if ch=='}':
                self.advance()
                self.add_token('RBRACE','}',sl,sc,'}')
                if self.cmd_depth>0:
                    self.cmd_depth-=1
                continue
            if self.cmd_depth>0:
                if ch=='|':
                    self.advance(); self.add_token('PIPE','|',sl,sc,'|'); continue
                if ch==';':
                    self.advance(); self.add_token('SEMI',';',sl,sc,';'); continue
                if ch=='?':
                    self.advance(); self.add_token('QUESTION','?',sl,sc,'?'); continue
                if ch=='<' and self.peek(1)=='<':
                    self.advance(); self.advance(); self.add_token('LTLT','<<',sl,sc,'<<'); continue
                if ch=='>' and self.peek(1)=='>':
                    self.advance(); self.advance(); self.add_token('GTGT','>>',sl,sc,'>>'); continue
                if ch in ('>','<'):
                    self.advance(); self.add_token(ch,ch,sl,sc,ch); continue
                if ch=='$':
                    nxt=self.peek(1)
                    if nxt=='{':
                        self.advance(); self.advance()
                        ident=''
                        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                            ident+=self.peek(); self.advance()
                        if self.pos<self.n and self.peek()=='}':
                            self.advance()
                            raw='${{'+ident+'}}'
                            self.add_token('CMD_VAR',ident,sl,sc,raw)
                        else:
                            self.err_inline(sl,sc,"unterminated variable")
                            raw='${{'+ident+'}}'
                            self.add_token('CMD_VAR',ident,sl,sc,raw)
                        continue
                    elif nxt.isalpha() or nxt=='_':
                        self.advance()
                        ident=''
                        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                            ident+=self.peek(); self.advance()
                        raw='${{'+ident+'}}'
                        self.add_token('CMD_VAR',ident,sl,sc,raw)
                        continue
                    else:
                        self.advance()
                        self.err_inline(sl,sc,"unexpected '$'.")
                        continue
                if ch=='\\':
                    esc_line=sl
                    esc_col=sc
                    self.advance()
                    if self.pos>=self.n:
                        self.err_inline(esc_line,esc_col,"invalid escape sequence '\\'.")
                        continue
                    esc=self.peek()
                    self.advance()
                    self.err_inline(esc_line,esc_col,f"invalid escape sequence '\\{esc}'.")
                    continue
                word=''
                wline=sl; wcol=sc
                in_single=False
                in_double=False
                while self.pos<self.n:
                    c=self.peek()
                    if in_single:
                        if c=="'":
                            word+=c
                            self.advance()
                            in_single=False
                            continue
                        elif c=='\\' and self.peek(1)=="'":
                            word+=c
                            self.advance()
                            word+=self.peek()
                            self.advance()
                            continue
                        else:
                            word+=c
                            self.advance()
                            continue
                    if in_double:
                        if c=='"':
                            word+=c
                            self.advance()
                            in_double=False
                            continue
                        elif c=='\\':
                            word+=c
                            self.advance()
                            if self.pos<self.n:
                                word+=self.peek()
                                self.advance()
                            continue
                        elif c=='$':
                            nxt=self.peek(1)
                            if nxt=='{':
                                self.advance(); self.advance()
                                ident=''
                                while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                                    ident+=self.peek(); self.advance()
                                if self.pos<self.n and self.peek()=='}':
                                    self.advance()
                                    word+='${{'+ident+'}}'
                                else:
                                    word+='${{'+ident+'}}'
                                continue
                            elif nxt.isalpha() or nxt=='_':
                                self.advance()
                                ident=''
                                while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                                    ident+=self.peek(); self.advance()
                                word+='${{'+ident+'}}'
                                continue
                            else:
                                word+=c
                                self.advance()
                                continue
                        else:
                            word+=c
                            self.advance()
                            continue
                    if c in ' \t\r\n#|;><&}':
                        break
                    if c=='?':
                        break
                    if c=="'":
                        in_single=True
                        word+=c
                        self.advance()
                        continue
                    if c=='"':
                        in_double=True
                        word+=c
                        self.advance()
                        continue
                    if c=='$':
                        nxt=self.peek(1)
                        if nxt=='{':
                            self.advance(); self.advance()
                            ident=''
                            while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                                ident+=self.peek(); self.advance()
                            if self.pos<self.n and self.peek()=='}':
                                self.advance()
                                word+='${{'+ident+'}}'
                            else:
                                word+='${{'+ident+'}}'
                            continue
                        elif nxt.isalpha() or nxt=='_':
                            self.advance()
                            ident=''
                            while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                                ident+=self.peek(); self.advance()
                            word+='${{'+ident+'}}'
                            continue
                        else:
                            word+=c
                            self.advance()
                            continue
                    if c=='\\':
                        nxt=self.peek(1)
                        esc_line=self.line
                        esc_col=self.col
                        self.advance()
                        esc=self.peek()
                        self.advance()
                        self.err_inline(esc_line,esc_col,f"invalid escape sequence '\\{esc}'.")
                        continue
                    if c=='{' or c=='}':
                        break
                    word+=c
                    self.advance()
                if word!='':
                    self.add_token('WORD',word,wline,wcol,word)
                    continue
                self.advance()
                self.err_inline(sl,sc,f"unexpected '{ch}'.")
                continue
            else:
                if ch=='"':
                    self.lex_string(sl,sc,inside=False); continue
                if ch=="'":
                    self.lex_char(sl,sc); continue
                if ch.isdigit():
                    self.lex_number(sl,sc); continue
                if ch.isalpha() or ch=='_':
                    self.lex_ident(sl,sc); continue
                if ch=='+' and self.peek(1)=='+':
                    self.advance(); self.advance(); self.add_token('PLUSPLUS','++',sl,sc,'++'); continue
                if ch=='=' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add_token('EQEQ','==',sl,sc,'=='); continue
                if ch=='!' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add_token('NEQ','!=',sl,sc,'!='); continue
                if ch=='<' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add_token('LTE','<=',sl,sc,'<='); continue
                if ch=='>' and self.peek(1)=='=':
                    self.advance(); self.advance(); self.add_token('GTE','>=',sl,sc,'>='); continue
                if ch=='<' and self.peek(1)=='<':
                    self.advance(); self.advance(); self.add_token('LTLT','<<',sl,sc,'<<'); continue
                if ch=='>' and self.peek(1)=='>':
                    self.advance(); self.advance(); self.add_token('GTGT','>>',sl,sc,'>>'); continue
                if ch=='@' and self.peek(1)=='[':
                    self.advance(); self.advance(); self.add_token('AT_LBRACK','@[',sl,sc,'@['); continue
                single_map={'=':'EQ','+':'PLUS','-':'MINUS','*':'STAR','/':'SLASH','%':'PERCENT',':':'COLON',',':'COMMA','.':'DOT','(':'LPAREN',')':'RPAREN','[':'LBRACK',']':'RBRACK','{':'LBRACE','}':'RBRACE','>':'GT','<':'LT','&':'AMP','!':'BANG','$':'DOLLAR'}
                if ch in single_map:
                    if ch=='$':
                        self.advance()
                        self.err_inline(sl,sc,"unexpected '$'.")
                        continue
                    self.advance()
                    self.add_token(single_map[ch],ch,sl,sc,ch)
                    continue
                self.advance()
                self.err_inline(sl,sc,f"unexpected '{ch}'.")
        return self.tokens
    def lex_string(self,line,col,inside=False):
        self.advance()
        buf=[]
        raw=['"']
        while self.pos<self.n:
            ch=self.peek()
            if ch=='"':
                self.advance()
                raw.append('"')
                break
            if ch=='\\':
                esc_col=self.col
                self.advance()
                if self.pos>=self.n:
                    self.err_inline(line,esc_col,"invalid escape sequence '\\'.")
                    buf.append('\\')
                    raw.append('\\')
                    break
                esc=self.peek()
                self.advance()
                raw.append('\\'+esc)
                if esc=='n':
                    buf.append('\n')
                elif esc=='t':
                    buf.append('\t')
                elif esc=='"':
                    buf.append('"')
                elif esc=="'":
                    buf.append("'")
                elif esc=='\\':
                    buf.append('\\')
                elif esc=='0':
                    buf.append('\0')
                else:
                    self.err_inline(line,esc_col,f"invalid escape sequence '\\{esc}'.")
                    buf.append('\0')
                continue
            if ch=='\n':
                self.err(line,col,"unterminated string")
                break
            if inside and ch=='$':
                nxt=self.peek(1)
                if nxt=='{':
                    self.advance(); self.advance()
                    ident=''
                    while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                        ident+=self.peek(); self.advance()
                    if self.pos<self.n and self.peek()=='}':
                        self.advance()
                        placeholder='${{'+ident+'}}'
                        buf.append(placeholder)
                        raw.append(placeholder)
                    else:
                        self.err_inline(line,col,"unterminated variable")
                    continue
                elif nxt.isalpha() or nxt=='_':
                    self.advance()
                    ident=''
                    while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
                        ident+=self.peek(); self.advance()
                    placeholder='${{'+ident+'}}'
                    buf.append(placeholder)
                    raw.append(placeholder)
                    continue
                else:
                    buf.append('$')
                    raw.append('$')
                    self.advance()
                    continue
            else:
                buf.append(ch)
                raw.append(ch)
                self.advance()
        s=''.join(buf)
        raw_str=''.join(raw)
        self.add_token('STRING',s,line,col,raw_str)
    def lex_char(self,line,col):
        self.advance()
        if self.pos>=self.n:
            self.err(line,col,"unterminated char")
            return
        ch=self.peek()
        if ch=='\\':
            esc_col=self.col
            self.advance()
            if self.pos>=self.n:
                self.err(line,col,"invalid escape")
                return
            esc=self.peek()
            self.advance()
            if esc not in ('n','t','"',"'" ,'\\','0'):
                self.err_inline(line,esc_col,f"invalid escape sequence '\\{esc}'.")
                val='\0'
                raw="'\\0'"
            else:
                if esc=='n':
                    val='\n'
                elif esc=='t':
                    val='\t'
                elif esc=='"':
                    val='"'
                elif esc=="'":
                    val="'"
                elif esc=='\\':
                    val='\\'
                elif esc=='0':
                    val='\0'
                else:
                    val=esc
                raw=f"'\\{esc}'"
        else:
            val=ch
            raw=f"'{ch}'"
            self.advance()
        if self.pos<self.n and self.peek()=="'":
            self.advance()
            self.add_token('CHAR',val,line,col,raw)
            return
        else:
            closing=self.src.find("'",self.pos)
            if closing!=-1:
                for i in range(self.pos,closing):
                    ce=self.src[i]
                    ecol=self.col + (i - self.pos)
                    self.err_inline(self.line,ecol,f"unexpected '{ce}'.")
                cnt= closing - self.pos + 1
                for _ in range(cnt):
                    self.advance()
                self.add_token('CHAR',val,line,col,raw)
                return
            else:
                self.err(line,col,"unterminated char")
                self.add_token('CHAR',val,line,col,raw)
                return
    def lex_ident(self,line,col):
        s=''
        while self.pos<self.n and (self.peek().isalnum() or self.peek()=='_'):
            s+=self.peek()
            self.advance()
        typ=KEYWORDS.get(s,'IDENT')
        self.add_token(typ,s,line,col,s)
    def lex_number(self,line,col):
        num_str=''
        while self.pos<self.n and self.peek().isdigit():
            num_str+=self.peek()
            self.advance()
        has_dot=False
        if self.pos<self.n and self.peek()=='.':
            if self.pos+1<self.n and self.peek(1).isdigit():
                has_dot=True
                num_str+='.'
                self.advance()
                while self.pos<self.n and self.peek().isdigit():
                    num_str+=self.peek()
                    self.advance()
        has_exp=False
        if self.pos<self.n and self.peek() in ('e','E'):
            if self.pos+1<self.n and self.peek(1).isdigit():
                has_exp=True
                expc=self.peek()
                self.advance()
                num_str+=expc
                while self.pos<self.n and self.peek().isdigit():
                    num_str+=self.peek()
                    self.advance()
        raw=num_str
        norm=raw
        try:
            if 'e' in raw.lower():
                mant,exp = raw.lower().split('e')
                mant_val=float(mant)
                exp_val=int(exp)
                val=mant_val*(10**exp_val)
                if float(val).is_integer():
                    norm=str(int(val))
                else:
                    norm=str(val)
                    if norm.endswith('.0'):
                        norm=norm[:-2]
            else:
                if not has_dot and not has_exp:
                    norm=str(int(raw)) if raw!='' else '0'
                else:
                    norm=raw
        except:
            norm=raw
        if has_dot or has_exp:
            try:
                v=float(raw)
            except:
                v=0.0
            self.add_token('FLOAT',v,line,col,norm)
        else:
            try:
                v=int(norm)
            except:
                v=0
            self.add_token('INT',v,line,col,norm)

def static_check(lexer, filename):
    errors=[]
    stack=[]
    declared=set(['std'])
    tokens=lexer.tokens
    for idx, tok in enumerate(tokens):
        if tok.typ=='LET':
            if idx+1 < len(tokens) and tokens[idx+1].typ=='IDENT':
                declared.add(tokens[idx+1].val)
        elif tok.typ=='FUNCTION':
            if idx+1 < len(tokens) and tokens[idx+1].typ=='IDENT':
                if idx+2 < len(tokens) and tokens[idx+2].typ=='LPAREN':
                    declared.add(tokens[idx+1].val)
            j=idx+1
            while j<len(tokens) and tokens[j].typ!='LPAREN':
                j+=1
            if j<len(tokens):
                j+=1
                while j<len(tokens) and tokens[j].typ!='RPAREN':
                    if tokens[j].typ=='IDENT':
                        declared.add(tokens[j].val)
                    j+=1
            stack.append('function')
        elif tok.typ=='FOR':
            if idx+1 < len(tokens) and tokens[idx+1].typ=='IDENT':
                declared.add(tokens[idx+1].val)
            stack.append('for')
        elif tok.typ=='WHILE':
            stack.append('while')
        elif tok.typ=='IF':
            stack.append('if')
        elif tok.typ=='END':
            if stack:
                stack.pop()
        elif tok.typ=='IDENT':
            is_decl=False
            if idx>0 and tokens[idx-1].typ=='LET':
                is_decl=True
            elif idx>0 and tokens[idx-1].typ=='DOT':
                is_decl=True
            elif idx+1 < len(tokens) and tokens[idx+1].typ=='COLON':
                is_decl=True
            elif idx>0 and tokens[idx-1].typ=='FOR':
                is_decl=True
            elif idx>0 and tokens[idx-1].typ=='FUNCTION':
                is_decl=True
            if is_decl:
                continue
            if tok.val not in declared:
                errors.append((tok.line, tok.col, f"undeclared variable '{tok.val}'"))
        elif tok.typ=='SELF':
            if 'function' not in stack:
                errors.append((tok.line, tok.col, "self keyword outside function"))
        elif tok.typ=='BREAK':
            if not any(s in ('for','while') for s in stack):
                errors.append((tok.line, tok.col, "break statement outside loop"))
        elif tok.typ=='RETURN':
            if 'function' not in stack:
                errors.append((tok.line, tok.col, "return statement outside function"))
        elif tok.typ=='CMD_VAR':
            if tok.val not in declared:
                errors.append((tok.line, tok.col, f"undeclared variable '{tok.val}'"))
        elif tok.typ=='WORD':
            import re
            for m in re.finditer(r'\$\{\{(\w+)\}\}', tok.raw):
                var=m.group(1)
                if var not in declared:
                    off=tok.raw.find(m.group(0))
                    col=tok.col + off + 2
                    errors.append((tok.line, col, f"undeclared variable '{var}'"))
    return errors

def print_lex(lexer, filename):
    out=[]
    out.append(DASH)
    for item in lexer.lex_items:
        if item[0]=='token':
            t=item[1]
            out.append(f"{filename} (line {t.line}, column {t.col}):\t{t.raw}")
        else:
            _,line,col,msg=item
            out.append(f"Error: line {line}, column {col} - {msg}")
    out.append(DASH)
    sys.stdout.write("\n".join(out)+"\n")
    seen=set()
    for line,col,msg in lexer.errors:
        if (line,col,msg) not in seen:
            seen.add((line,col,msg))
            sys.stderr.write(f"Error: {filename} (line {line}, column {col}) - {msg}\n")

# Native interpreter
class HushChar(str):
    pass

class ReturnSig(Exception):
    def __init__(self,val): self.val=val
class BreakSig(Exception): pass

class Func:
    def __init__(self,params,body,env, pos):
        self.params=params
        self.body=body
        self.env=env
        self.pos=pos

class Interp:
    def __init__(self, source, filename, args_for_script):
        self.source=source
        self.filename=filename
        self.args_for_script=args_for_script
        self.globals={}
        self.init_std()

    def init_std(self):
        import math, random, glob, json as js, base64, binascii, re, pathlib
        std={}
        def to_str(v):
            if v is None: return "nil"
            if v is True: return "true"
            if v is False: return "false"
            if isinstance(v, int) and not isinstance(v,bool): return str(v)
            if isinstance(v, float):
                s=str(v)
                if '.' not in s:
                    s+='.0'
                return s
            if isinstance(v, HushChar): return str(v)
            if isinstance(v, str): return v
            if isinstance(v, list):
                parts=[]
                for x in v:
                    if isinstance(x, HushChar): parts.append(str(x))
                    elif isinstance(x, str): parts.append('"'+x+'"')
                    elif isinstance(x, Func): parts.append(f"function<{self.filename} (line 1, column 10)>")
                    else: parts.append(to_str(x))
                return "[ "+ ", ".join(parts)+" ]" if parts else "[ ]"
            if isinstance(v, dict):
                if not v: return "@[ ]"
                parts=[]
                for k, val in v.items():
                    if isinstance(val, str) and not isinstance(val, HushChar):
                        vs='"'+val+'"'
                    else: vs=to_str(val)
                    parts.append(f'"{k}": {vs}')
                return "@[ "+ ", ".join(parts)+" ]"
            if isinstance(v, Func): return f"function<{self.filename} (line 1, column 10)>"
            if callable(v): return getattr(v,'_name', str(v))
            if isinstance(v, dict) and '_error' in v: return f"error: \"{v['_pos']}\" (\"{v['_msg']}\")"
            return str(v)
        def typ(v):
            if v is None: return "nil"
            if v is True or v is False: return "bool"
            if isinstance(v, int) and not isinstance(v,bool): return "int"
            if isinstance(v, float): return "float"
            if isinstance(v, HushChar): return "char"
            if isinstance(v, str): return "string"
            if isinstance(v, list): return "array"
            if isinstance(v, dict) and '_error' not in v: return "dict"
            if isinstance(v, Func) or callable(v): return "function"
            if isinstance(v, dict) and '_error' in v: return "error"
            return "unknown"
        def is_empty(v):
            if v is None: return True
            if isinstance(v, (str, HushChar)): return len(v)==0
            if isinstance(v, list): return len(v)==0
            if isinstance(v, dict): return len(v)==0
            return False
        def hush_len(v):
            if isinstance(v, (str, HushChar, list, dict)): return len(v)
            raise self.panic(f"value ({to_str(v)}) has unexpected type, expected string, array or dict")
        def hush_contains(s, ch):
            if not isinstance(s, (str, HushChar)): raise self.panic(f"value ({to_str(s)}) has unexpected type, expected string")
            if not isinstance(ch, HushChar): raise self.panic(f"value ({to_str(ch)}) has unexpected type, expected char")
            return str(ch) in str(s)
