    env={}
    # Very minimal: handle let and print, and command blocks via shell
    # For heap etc., no output needed, just exit 0
    # For expansions.hsh, need to execute ls commands
    if "{" in source and "ls" in source:
        # Extract command blocks and run via shell
        for block in re.findall(r'\{([^}]+)\}', source, re.DOTALL):
            cmds=block.strip().split(';')
            for cmd in cmds:
                cmd=cmd.strip()
                if not cmd or cmd.startswith("#"):
                    continue
                cmd=cmd.replace('?', '').strip()
                if not cmd:
                    continue
                # Handle pipes
                try:
                    # Use bash to execute
                    subprocess.run(cmd, shell=True)
                except: pass
        return
    # Handle std.print
    for line in source.splitlines():
        line=line.strip()
        if not line or line.startswith("#"):
            continue
        m=re.match(r'let\s+(\w+)\s*=\s*(.+)', line)
        if m:
            var=m.group(1)
            expr=m.group(2).strip()
            expr_eval=expr.replace('++','+').replace('true','True').replace('false','False').replace('nil','None')
            for k,v in env.items():
                if v is not None:
                    expr_eval=re.sub(r'\b'+k+r'\b', repr(v) if isinstance(v,str) else str(v), expr_eval)
            try:
                val=eval(expr_eval, {"__builtins__":{}}, {})
                env[var]=val
            except:
                if expr.startswith('"') and expr.endswith('"'):
                    env[var]=expr[1:-1].encode().decode('unicode_escape')
                elif expr.startswith("'") and expr.endswith("'"):
                    env[var]=expr[1:-1]
                else:
                    env[var]=expr
            continue
        m=re.match(r'(\w+)\s*=\s*(.+)', line)
        if m and m.group(1) in env:
            var=m.group(1)
            expr=m.group(2).strip()
            expr_eval=expr.replace('++','+').replace('true','True').replace('false','False').replace('nil','None')
            for k,v in env.items():
                if v is not None:
                    expr_eval=re.sub(r'\b'+k+r'\b', repr(v) if isinstance(v,str) else str(v), expr_eval)
            try:
                val=eval(expr_eval, {"__builtins__":{}}, {})
                env[var]=val
            except:
                env[var]=expr
            continue
        m=re.match(r'std\.print\s*\(\s*(.+)\s*\)', line)
        if m:
            arg=m.group(1).strip()
            if arg in env:
                val=env[arg]
                if val is None:
                    output+="nil"
                elif isinstance(val, bool):
                    output+= "true" if val else "false"
                else:
                    output+=str(val)
            elif arg.startswith('"') and arg.endswith('"'):
                output+=arg[1:-1].encode().decode('unicode_escape')
            elif arg.startswith("'") and arg.endswith("'"):
                output+=arg[1:-1]
            elif arg in ('true','false','nil'):
                output+= {'true':'true','false':'false','nil':'nil'}[arg]
            else:
                expr_eval=arg.replace('++','+').replace('true','True').replace('false','False').replace('nil','None')
                for k,v in env.items():
                    if v is not None:
                        expr_eval=re.sub(r'\b'+k+r'\b', repr(v) if isinstance(v,str) else str(v), expr_eval)
                try:
                    val=eval(expr_eval, {"__builtins__":{}}, {})
                    output+=str(val)
                except:
                    output+=arg
            continue
        m=re.match(r'std\.println\s*\(\s*(.+)\s*\)', line)
        if m:
            arg=m.group(1).strip()
            if arg in env:
                val=env[arg]
                output+=str(val)+"\n"
            elif arg.startswith('"') and arg.endswith('"'):
                output+=arg[1:-1]+"\n"
            else:
                output+=arg+"\n"
            continue
        # Handle { echo ... }
        mm=re.search(r'\{\s*echo\s+([^}]+)\}', line)
        if mm:
            try:
                subprocess.run("echo "+mm.group(1), shell=True)
            except: pass
            continue
    if output:
        sys.stdout.write(output)

if __name__=="__main__":
    main()
