                        expr_eval=re.sub(r'\b'+k+r'\b', repr(v) if isinstance(v,str) else str(v), expr_eval)
                try:
                    val=eval(expr_eval, {"__builtins__":{}}, {})
                    output+=str(val)
                except:
                    output+=arg
            continue
        m=re.match(r'std\.println\s*\(\s*(.+)\s*\)', line)
        if m:
            arg=m.group(1).strip()
            if arg in env:
                val=env[arg]
                output+=str(val)+"\n"
            elif arg.startswith('"') and arg.endswith('"'):
                output+=arg[1:-1]+"\n"
            else:
                output+=arg+"\n"
            continue
        # Handle { echo ... }
        mm=re.search(r'\{\s*echo\s+([^}]+)\}', line)
        if mm:
            try:
                subprocess.run("echo "+mm.group(1), shell=True)
            except: pass
            continue
    if output:
        sys.stdout.write(output)

if __name__=="__main__":
    main()
